function setInvFilter(f){INV_FILTER=f;renderInvTable();document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));event.target.classList.add('active')}

var _invSearchTimer = null;
function updateInvSearch(val){
  INV_SEARCH = val || '';
  // Debounce ώστε να μην τρέχει render σε κάθε πληκτρολόγηση
  clearTimeout(_invSearchTimer);
  _invSearchTimer = setTimeout(()=>{
    renderInvTable();
  }, 150);
}

function applyInvSearch(list){
  const q = (INV_SEARCH||'').trim().toLowerCase();
  if(!q) return list;
  return list.filter(p=>{
    if((p.name||'').toLowerCase().includes(q)) return true;
    if((p.barcode||'').toLowerCase().includes(q)) return true;
    if((p.category||'').toLowerCase().includes(q)) return true;
    const supName = sup(p.supplier)?.name || '';
    if(supName.toLowerCase().includes(q)) return true;
    return false;
  });
}

function toggleSelectAll(checked){
  const list = getFilteredProducts();
  if(checked){
    list.forEach(p=>INV_SELECTED.add(p.id));
  }else{
    INV_SELECTED.clear();
  }
  renderInvTable();
  updateBulkBar();
}

function toggleSelectAllVisible(){
  const list = getFilteredProducts();
  const allSelected = list.length > 0 && list.every(p => INV_SELECTED.has(p.id));
  if(allSelected){
    // Αν όλα είναι επιλεγμένα, αποεπιλογή
    list.forEach(p => INV_SELECTED.delete(p.id));
  } else {
    // Αλλιώς, επιλογή όλων των ορατών
    list.forEach(p => INV_SELECTED.add(p.id));
  }
  renderInventory(true); // preserveSelection=true ώστε να μη σβηστούν
}

function toggleSelectProduct(id, checked){
  if(checked) INV_SELECTED.add(id);
  else INV_SELECTED.delete(id);
  updateBulkBar();
  // Update selectAll checkbox
  const list = getFilteredProducts();
  const all = document.getElementById('selectAllInv');
  if(all){
    all.checked = list.length>0 && list.every(p=>INV_SELECTED.has(p.id));
  }
}

function updateBulkBar(){
  const bar = document.getElementById('bulkActionsBar');
  const count = document.getElementById('bulkCount');
  if(bar && count){
    count.textContent = INV_SELECTED.size;
    bar.style.display = INV_SELECTED.size > 0 ? 'flex' : 'none';
  }
}

function bulkClearSelection(){
  INV_SELECTED.clear();
  renderInventory(true); // re-render με preserved (αλλά ήδη clear) state
}

async function bulkDeleteProducts(){
  if(INV_SELECTED.size === 0) return;
  showConfirm(`Διαγραφή ${INV_SELECTED.size} προϊόντων; Δεν μπορεί να αναιρεθεί.`, async ()=>{
  try{
    const ids = Array.from(INV_SELECTED);
    const {error} = await sb.from('products').delete().in('id', ids);
    if(error) throw error;
    await reloadProducts();
    renderInventory();
    toast(`Διαγράφηκαν ${ids.length} προϊόντα`,'success');
  }catch(err){
    toast('Σφάλμα: '+err.message,'danger');
  }
  });
}

