// ════════════════════════════════════════════════════════════════════════
// 🔍 SMART SUPPLIER MATCHING — αναγνωρίζει "VapeExperts" = "Παπαδάκος Εμμανουήλ"
// ════════════════════════════════════════════════════════════════════════
// Στρατηγική (αυστηρά → χαλαρά):
//   1. Match σε ΑΦΜ/VIES (το πιο αξιόπιστο)
//   2. Match σε όνομα (exact)
//   3. Match σε όνομα μετά από normalization
//   4. Match σε notes/contact του προμηθευτή (για "trade name" συσχέτιση)
//   5. Token-based match (για "VapeExperts" vs "Vape Experts ΟΕ")
function _normalizeSupplierName(s){
  if(!s) return '';
  let n = String(s);
  // Αφαίρεση legal forms ΠΡΙΝ από οτιδήποτε άλλο — με πολλαπλά variants
  // Επιτρέπει spaces μεταξύ letters (π.χ. "Ι. Κ. Ε." ή "Ι.Κ.Ε.")
  n = n.replace(/\b(Ο\s*\.\s*Ε\.?|O\s*\.\s*E\.?|ΟΕ|OE)\b/g,' ')
       .replace(/\b(Ε\s*\.\s*Π\s*\.\s*Ε\.?|E\s*\.\s*P\s*\.\s*E\.?|ΕΠΕ|EPE)\b/g,' ')
       .replace(/\b(Α\s*\.\s*Ε\.?|A\s*\.\s*E\.?|ΑΕ|AE)\b/g,' ')
       .replace(/\b(Ι\s*\.\s*Κ\s*\.\s*Ε\.?|I\s*\.\s*K\s*\.\s*E\.?|ΙΚΕ|IKE)\b/g,' ')
       .replace(/\b(Μ\s*\.\s*Ε\s*\.\s*Π\s*\.\s*Ε\.?|M\s*\.\s*E\s*\.\s*P\s*\.\s*E\.?|ΜΕΠΕ|MEPE)\b/g,' ')
       .replace(/\b(Ltd\.?|Inc\.?|LLC|GmbH|S\.A\.?|S\.r\.l\.?|SRL|BV|Sp\.?\s*z\.?\s*o\.?\s*o\.?)\b/gi,' ');
  // Lowercase + remove accents
  n = n.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  // Καθάρισμα
  n = n.replace(/[^a-z0-9α-ω]+/gi,' ').replace(/\s+/g,' ').trim();
  // Αφαίρεση orphan single-letter Greek tokens που ίσως έμειναν
  n = n.split(' ').filter(t => t.length >= 2 || /[a-z0-9]/.test(t)).join(' ');
  return n;
}

function _findSupplierSmart(supplierName, supplierVat){
  if(!Array.isArray(SUPPLIERS) || SUPPLIERS.length === 0) return null;
  
  // 1. ΑΦΜ/VIES match (πιο αξιόπιστο)
  if(supplierVat){
    const vatNorm = String(supplierVat).replace(/\s+/g,'').toUpperCase();
    const vatExact = SUPPLIERS.find(s => 
      (s.vies_number && String(s.vies_number).replace(/\s+/g,'').toUpperCase() === vatNorm) ||
      (s.vat_number && String(s.vat_number).replace(/\s+/g,'').toUpperCase() === vatNorm)
    );
    if(vatExact) return vatExact;
    // Σύγκριση μόνο των αριθμητικών μερών (αν το VIES περιέχει "GR123456789")
    const vatDigits = vatNorm.replace(/[^0-9]/g,'');
    if(vatDigits.length >= 8){
      const vatDigitsMatch = SUPPLIERS.find(s => {
        const sd = String(s.vies_number||s.vat_number||'').replace(/[^0-9]/g,'');
        return sd && sd === vatDigits;
      });
      if(vatDigitsMatch) return vatDigitsMatch;
    }
  }
  
  if(!supplierName) return null;
  const targetNorm = _normalizeSupplierName(supplierName);
  if(!targetNorm) return null;
  
  // 2. Exact match στο όνομα (μετά από normalization)
  const exact = SUPPLIERS.find(s => _normalizeSupplierName(s.name) === targetNorm);
  if(exact) return exact;
  
  // 3. Match σε notes/contact (για "trade names" όπως VapeExperts → Παπαδάκος)
  const inNotes = SUPPLIERS.find(s => {
    const notesNorm = _normalizeSupplierName(s.notes || '');
    const contactNorm = _normalizeSupplierName(s.contact || '');
    return (notesNorm && (notesNorm.includes(targetNorm) || targetNorm.includes(notesNorm))) ||
           (contactNorm && (contactNorm.includes(targetNorm) || targetNorm.includes(contactNorm)));
  });
  if(inNotes) return inNotes;
  
  // 4. Token-based match (σπάει σε λέξεις και βλέπει αν ταιριάζουν >=70%)
  const targetTokens = targetNorm.split(' ').filter(t => t.length >= 3);
  if(targetTokens.length === 0) return null;
  
  let best = null, bestRatio = 0;
  for(const s of SUPPLIERS){
    const candidates = [s.name, s.contact, s.notes].filter(Boolean);
    for(const cand of candidates){
      const candNorm = _normalizeSupplierName(cand);
      if(!candNorm) continue;
      const candTokens = new Set(candNorm.split(' ').filter(t => t.length >= 3));
      if(candTokens.size === 0) continue;
      const matched = targetTokens.filter(t => 
        candTokens.has(t) || [...candTokens].some(ct => ct.includes(t) || t.includes(ct))
      ).length;
      const ratio = matched / targetTokens.length;
      if(ratio > bestRatio){
        bestRatio = ratio;
        best = s;
      }
    }
  }
  if(bestRatio >= 0.7) return best;
  return null;
}

// Auto-create supplier με τα δεδομένα του τιμολογίου
async function _autoCreateSupplier(inv){
  if(!inv.supplierName) return null;
  const ct = inv.invoiceType === 'intraeu' ? 'EU' : (inv.invoiceType === 'import' ? 'NON_EU' : 'GR');
  try{
    const { data: newSup, error } = await sb.from('suppliers').insert({
      shop_id: SHOP_ID,
      name: inv.supplierName,
      vies_number: inv.supplierVat || null,
      country_type: ct,
      country_code: inv.supplierCountry || (ct==='GR'?'GR':''),
      notes: '🤖 Δημιουργήθηκε αυτόματα από Invoice Scanner'
    }).select().single();
    if(!error && newSup){
      SUPPLIERS.push(newSup);
      return newSup;
    }
    if(error) console.warn('[AutoCreate Supplier] error:', error.message);
  }catch(e){
    console.warn('[AutoCreate Supplier] exception:', e);
  }
  return null;
}
window._findSupplierSmart = _findSupplierSmart;
window._autoCreateSupplier = _autoCreateSupplier;

// Helper: αναγνωρίζει αν μια γραμμή τιμολογίου είναι ΕΞΟΔΟ (μεταφορικά, αμοιβή
// τρόπου πληρωμής, αντικαταβολή κλπ.) και ΟΧΙ προϊόν. Τέτοιες γραμμές μπαίνουν
// στο purchase entry ως extra_fees αλλά ΔΕΝ δημιουργούν προϊόν στην αποθήκη.
function _isFeeLine(line){
  if(!line || !line.description) return false;
  const desc = String(line.description).toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  // Αν έχει volumeMl > 0, μάλλον είναι κανονικό προϊόν (όχι έξοδο)
  if(line.volumeMl && line.volumeMl > 0) return false;
  // Greek + English fee keywords
  const feeKeywords = [
    'εξοδα αποστολ',     // έξοδα αποστολής
    'εξοδα μεταφορ',     // έξοδα μεταφοράς
    'μεταφορικα',        // μεταφορικά
    'εξοδα τροπου',      // έξοδα τρόπου πληρωμής
    'τροπος πληρωμ',     // τρόπος πληρωμής
    'αντικαταβολ',       // αντικαταβολή
    'εξοδα συσκευασ',    // έξοδα συσκευασίας
    'courier',
    'shipping',
    'shipping fee',
    'delivery fee',
    'delivery cost',
    'cod fee',           // cash on delivery
    'cash on delivery',
    'payment fee',
    'transaction fee',
    'handling fee',
    'service charge',
    'packaging'
  ];
  return feeKeywords.some(k => desc.includes(k));
}
window._isFeeLine = _isFeeLine;

// ── Image compression helper για εικόνες τιμολογίων μεγάλου μεγέθους ───
// Auto-compress: αν εικόνα > 5MB, μειώνει διαστάσεις/ποιότητα ώστε να κατέβει < 5MB.
// PDFs δεν συμπιέζονται (περνούν ως έχουν).
async function _compressImageIfNeeded(file){
  if(!file) return file;
  const isImage = file.type && file.type.startsWith('image/');
  // PDFs ή μικρές εικόνες: ως έχουν
  if(!isImage || file.size <= 5 * 1024 * 1024) return file;
  
  return new Promise((resolve) => {
    try{
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
          // Calculate new dimensions: max 2400px στη μεγαλύτερη πλευρά
          let { width, height } = img;
          const maxDim = 2400;
          if(width > maxDim || height > maxDim){
            const ratio = width > height ? maxDim / width : maxDim / height;
            width = Math.round(width * ratio);
            height = Math.round(height * ratio);
          }
          
          const canvas = document.createElement('canvas');
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          // White background για JPG (αποφυγή μαύρου background από αλφα)
          ctx.fillStyle = '#FFFFFF';
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(img, 0, 0, width, height);
          
          // Try compression with decreasing quality
          canvas.toBlob((blob) => {
            if(!blob){ resolve(file); return; }
            // Δημιουργία νέου File με σωστό όνομα
            const compressedName = file.name.replace(/\.[^.]+$/, '') + '.jpg';
            const compressedFile = new File([blob], compressedName, { type: 'image/jpeg' });
            const reduction = ((1 - compressedFile.size / file.size) * 100).toFixed(0);
            console.log(`[Compress] ${(file.size/1024/1024).toFixed(1)}MB → ${(compressedFile.size/1024/1024).toFixed(1)}MB (-${reduction}%)`);
            resolve(compressedFile);
          }, 'image/jpeg', 0.85); // 85% quality (καλή ισορροπία ποιότητας/μεγέθους)
        };
        img.onerror = () => resolve(file);
        img.src = e.target.result;
      };
      reader.onerror = () => resolve(file);
      reader.readAsDataURL(file);
    }catch(err){
      console.warn('[Compress] failed:', err);
      resolve(file);
    }
  });
}
window._compressImageIfNeeded = _compressImageIfNeeded;

// Helper: εξάγει ml αρώματος από γραμμή τιμολογίου με smart fallbacks.
// Σειρά προτεραιότητας:
//   1. line.aromaMl (αν το έδωσε ρητά το ZyroNex prompt)
//   2. Pattern "30ml (120ml)" ή "12/60ml" στο όνομα → πρώτο νούμερο
//   3. Match με υπάρχον προϊόν → product.shortfillMl
//   4. Default 0 (καμία τιμή — ο χρήστης μπορεί να προσθέσει χειροκίνητα)
function _getLineAromaMl(line){
  if(!line) return 0;
  // Αν είναι fee/shipping → 0 (δεν υπόκειται σε ΕΦΚ)
  if(_isFeeLine(line)) return 0;
  
  // 1. Direct aromaMl από AI
  if(line.aromaMl != null && line.aromaMl > 0){
    return Number(line.aromaMl);
  }
  
  const desc = String(line.description || '');
  
  // 2. Pattern "30ml (120ml)" — Ελληνικό longfill format
  // Παίρνουμε το πρώτο νούμερο (άρωμα) όταν έχει την παρένθεση μετά
  let m = desc.match(/(\d+(?:\.\d+)?)\s*ml\s*\(\s*(\d+(?:\.\d+)?)\s*ml\s*\)/i);
  if(m){
    const first = parseFloat(m[1]);
    const second = parseFloat(m[2]);
    // Sanity check: το πρώτο πρέπει να είναι μικρότερο (άρωμα < τελικό μπουκάλι)
    if(first > 0 && first < second) return first;
  }
  
  // 3. Pattern "12/60ml" — άλλο format για longfill
  m = desc.match(/(\d+(?:\.\d+)?)\s*\/\s*(\d+(?:\.\d+)?)\s*ml/i);
  if(m){
    const first = parseFloat(m[1]);
    const second = parseFloat(m[2]);
    if(first > 0 && first < second) return first;
  }
  
  // 4. Match με υπάρχον προϊόν → χρησιμοποιούμε το shortfillMl του
  if(typeof findBestProductMatch === 'function'){
    const match = findBestProductMatch(line);
    if(match && match.product && match.product.shortfillMl > 0){
      return Number(match.product.shortfillMl);
    }
  }
  
  // 5. Για boosters/nicshots/premix: το aromaMl == volumeMl
  // (Έλεγχος με keywords)
  const lc = desc.toLowerCase();
  const isBooster = lc.includes('booster') || lc.includes('nicshot') || lc.includes('nic shot') || lc.includes('νικοτιν');
  const isPremix = lc.includes('premix');
  if((isBooster || isPremix) && line.volumeMl > 0){
    return Number(line.volumeMl);
  }
  
  // 6. Δεν μπορούμε να βγάλουμε άκρη — επιστρέφουμε 0 (ασφαλές fallback,
  //    ο χρήστης βλέπει 0€ ΕΦΚ και μπορεί να το διορθώσει χειροκίνητα)
  return 0;
}
window._getLineAromaMl = _getLineAromaMl;

// Helper: εντοπίζει προϊόντα που μάλλον είναι έξοδα/μεταφορικά (από παλιό bug)
// και τα προτείνει για διαγραφή.
async function _findFeeProducts(){
  if(typeof PRODUCTS === 'undefined' || !Array.isArray(PRODUCTS)) return [];
  const candidates = PRODUCTS.filter(p => {
    // Έλεγχος σαν να ήταν invoice line
    return _isFeeLine({ description: p.name, volumeMl: p.volumeMl });
  });
  return candidates;
}
window._findFeeProducts = _findFeeProducts;

async function cleanupFeeProducts(){
  const fees = await _findFeeProducts();
  if(fees.length === 0){
    if(typeof toast === 'function') toast('Δεν βρέθηκαν προϊόντα-έξοδα', 'info');
    return;
  }
  const list = fees.map(p => `• ${p.name} (stock: ${p.stock||0})`).join('\n');
  const proceed = confirm(`Βρέθηκαν ${fees.length} προϊόντα που μοιάζουν να είναι έξοδα (μεταφορικά, αμοιβές):\n\n${list}\n\nΘέλεις να ΔΙΑΓΡΑΦΟΥΝ; (Δεν θα επηρεάσει το ιστορικό αγορών)`);
  if(!proceed) return;
  
  let deleted = 0, failed = 0;
  for(const p of fees){
    try{
      const { error } = await sb.from('products').delete().eq('id', p.id);
      if(!error){
        deleted++;
        // Αφαίρεση από local cache
        const idx = PRODUCTS.findIndex(x => x.id === p.id);
        if(idx >= 0) PRODUCTS.splice(idx, 1);
      } else {
        failed++;
      }
    }catch(_){ failed++; }
  }
  if(typeof toast === 'function'){
    toast(`✅ Διαγράφηκαν ${deleted} προϊόντα-έξοδα${failed?` (${failed} απέτυχαν)`:''}`, 'success');
  }
  if(typeof renderInventory === 'function') renderInventory(true);
}
window.cleanupFeeProducts = cleanupFeeProducts;

async function importInvoiceToPurchases(inv, efkAmount) {
  try {
    // 1. Έλεγχος για διπλό τιμολόγιο
    if(inv.invoiceNumber && inv.supplierVat){
      const dup = await INVOICE_ARCHIVE.checkDuplicate(inv.supplierVat, inv.invoiceNumber, inv.invoiceDate);
      if(dup.exists){
        const m = dup.matches[0];
        const proceed = confirm(
          `⚠️ Το τιμολόγιο "${inv.invoiceNumber}" από αυτόν τον προμηθευτή υπάρχει ήδη στις ${m.purchase_date} (${eur(m.gross_amount||0)}).\n\nΘέλεις να συνεχίσεις παρά τον διπλασιασμό;`
        );
        if(!proceed){ closeModal(); return null; }
      }
    }

    // 2. Smart supplier matching (όχι μόνο σε όνομα/ΑΦΜ — και σε notes/aliases)
    let supplier = _findSupplierSmart(inv.supplierName, inv.supplierVat);

    // Auto-create supplier αν δεν υπάρχει
    if(!supplier && inv.supplierName){
      supplier = await _autoCreateSupplier(inv);
    }

    // 3. Upload εικόνας/PDF στο Storage (ΠΑΝΤΑ — ακόμα και χωρίς supplier)
    let invoiceImageUrl = null;
    let uploadFailReason = null;
    if(window._lastInvoiceFile){
      const uploadRes = await INVOICE_ARCHIVE.upload(
        window._lastInvoiceFile, 
        supplier ? supplier.id : null, // null αν δεν έχουμε supplier — μπαίνει σε no-supplier folder
        inv.invoiceDate, 
        inv.invoiceNumber
      );
      if(uploadRes.success){
        invoiceImageUrl = uploadRes.path;
      } else {
        uploadFailReason = uploadRes.error || 'unknown';
        console.error('[Invoice] STORAGE UPLOAD FAILED:', uploadFailReason);
        console.error('[Invoice] File:', window._lastInvoiceFile.name, 'Size:', window._lastInvoiceFile.size);
        // Visible warning toast — δεν αφήνουμε σιωπηλή αποτυχία
        if(typeof toast === 'function'){
          if(/policy|permission|denied|forbidden|unauthorized|RLS/i.test(uploadFailReason)){
            toast(`⚠️ Αποθήκευση αρχείου απέτυχε: λείπει Storage RLS policy. Πες στον admin να τρέξει το νέο SQL.`, 'danger', 7000);
          } else {
            toast(`⚠️ Δεν αρχειοθετήθηκε το PDF: ${uploadFailReason}`, 'warning', 5000);
          }
        }
      }
    }

    // 4. Insert purchase entry με όλα τα πεδία
    // Πεδία που μπορεί να ΛΕΙΠΟΥΝ από schema παλαιότερων εγκαταστάσεων.
    // Αν το insert αποτύχει με "Could not find column", αφαιρούμε αυτά τα optional fields
    // και ξαναδοκιμάζουμε. Έτσι το system δουλεύει ακόμα και πριν τρέξει η νέα migration.
    const purchaseData = {
      shop_id: SHOP_ID,
      supplier_id: supplier?.id || null,
      supplier_name: inv.supplierName || 'Άγνωστος',
      invoice_number: inv.invoiceNumber || '',
      purchase_date: inv.invoiceDate || today,
      net_amount: inv.netAmount || 0,
      vat_amount: inv.vatAmount || 0,
      gross_amount: inv.grossAmount || 0,
      efk_amount: efkAmount || 0,
      invoice_type: inv.invoiceType || 'greek',
      is_reverse_charge: inv.isReverseCharge || false,
      currency: inv.currency || 'EUR',
      invoice_image_url: invoiceImageUrl,
      mark: inv.mark || null,
      notes: `📄 Smart Invoice Scanner · ${inv.invoiceType === 'intraeu' ? 'Ενδοκοινοτική Απόκτηση' : inv.invoiceType === 'import' ? 'Εισαγωγή' : 'Ελληνικό Τιμολόγιο'}${invoiceImageUrl ? ' · 📎 PDF αρχειοθετήθηκε' : ''}`,
      lines: inv.lines || []
    };

    let insertError = null;
    let { error } = await sb.from('purchases').insert(purchaseData);
    insertError = error;

    // Graceful degradation: αν λείπει στήλη, αφαιρώ ΜΟΝΟ αυτή και ξαναδοκιμάζω
    // (loop μέχρι 6 retries για περίπτωση που λείπουν πολλές στήλες)
    let retries = 0;
    let dataToInsert = { ...purchaseData };
    let removedColumns = [];
    while(insertError && retries < 6 && /Could not find.*column|column .* does not exist|schema cache/i.test(insertError.message || '')){
      // Extract column name από το error: "Could not find the 'currency' column"
      const m = (insertError.message || '').match(/'([^']+)'\s*column|column\s+"([^"]+)"\s*does not exist|column\s+'([^']+)'/i);
      const missingCol = m ? (m[1] || m[2] || m[3]) : null;
      if(!missingCol) break;
      console.warn(`[Invoice] Schema missing column "${missingCol}" — removing from payload`);
      delete dataToInsert[missingCol];
      removedColumns.push(missingCol);
      retries++;
      const retry = await sb.from('purchases').insert(dataToInsert);
      insertError = retry.error;
    }

    // Αν πέρασε με αφαίρεση columns, ενημέρωσε τον χρήστη ότι χρειάζεται upgrade
    if(!insertError && removedColumns.length > 0){
      const lostInfo = [];
      if(removedColumns.includes('efk_amount') && efkAmount > 0) lostInfo.push(`ΕΦΚ: ${efkAmount.toFixed(2)}€`);
      if(removedColumns.includes('mark') && inv.mark) lostInfo.push(`MARK: ${inv.mark}`);
      if(removedColumns.includes('invoice_image_url') && invoiceImageUrl) lostInfo.push(`PDF: ${invoiceImageUrl}`);
      console.warn('[Invoice] Inserted in basic mode. Missing columns:', removedColumns);
      toast(`⚠️ Καταχωρήθηκε αλλά ΛΕΙΠΟΥΝ στήλες (${removedColumns.join(', ')}) — τρέξε το νέο SQL!`, 'warning', 7000);
    }
    
    if (insertError) throw insertError;

    const supplierMsg = supplier ? ` → ${supplier.name}` : '';
    toast(`✅ Τιμολόγιο καταχωρήθηκε${supplierMsg}${invoiceImageUrl?' + αρχειοθετήθηκε':''}!`, 'success');
    
    // Cleanup global state
    window._lastInvoiceFile = null;
    
    closeModal();
    if(typeof renderPurchases === 'function') await renderPurchases();
    
    // Επιστρέφει το supplier.id για να το χρησιμοποιήσει το importInvoiceBoth
    return supplier ? supplier.id : null;
  } catch(e) {
    console.error('[Invoice] import error:', e);
    toast('Σφάλμα: ' + (e.message || 'Άγνωστο'), 'danger');
    return null;
  }
}

async function importInvoiceToInventory(inv, supplierIdHint) {
  const allLines = (inv.lines || []).filter(l => l.quantity > 0);
  // Φιλτράρω fee/shipping/payment lines — δεν είναι προϊόντα, είναι έξοδα
  const lines = allLines.filter(l => !_isFeeLine(l));
  const skippedFees = allLines.length - lines.length;
  let updated = 0, created = 0, skipped = 0;

  // Find supplier (από hint ή lookup ή auto-create) — για να μπει supplier_id σε όλες
  // τις γραμμές (νέες και υπάρχουσες). Έτσι στην καρτέλα προμηθευτή φαίνονται όλα τα προϊόντα του.
  let supplierForLines = null;
  if(supplierIdHint){
    supplierForLines = SUPPLIERS.find(s => s.id === supplierIdHint);
  }
  if(!supplierForLines && inv.supplierName){
    supplierForLines = _findSupplierSmart(inv.supplierName, inv.supplierVat);
  }
  // Αν δεν βρέθηκε, κάνε auto-create — να μην χάσουμε attribution
  if(!supplierForLines && inv.supplierName){
    supplierForLines = await _autoCreateSupplier(inv);
  }

  // Default category για auto-created προϊόντα
  const defaultCategory = (CATEGORIES.find(c => c && c !== 'Όλα') || 'Άλλα');

  for (const line of lines) {
    // Check checkbox state
    const idx = lines.indexOf(line);
    const checkbox = document.getElementById(`line_${idx}`);
    if(checkbox && !checkbox.checked){ skipped++; continue; }

    // 1. Improved fuzzy matching
    const matchResult = findBestProductMatch(line);
    
    if (matchResult && matchResult.product) {
      const matched = matchResult.product;
      const newStock = (matched.stock || 0) + (line.quantity || 0);
      const newCost = line.unitPrice > 0 ? line.unitPrice : matched.cost;
      // Update fields object
      const updateFields = { stock: newStock, cost: newCost };
      // Αν δεν είχε supplier και τώρα έχουμε ένα — μπες
      if(!matched.supplier && supplierForLines){
        updateFields.supplier_id = supplierForLines.id;
      }
      const { error } = await sb.from('products').update(updateFields).eq('id', matched.id);
      if(!error){
        matched.stock = newStock;
        matched.cost = newCost;
        if(updateFields.supplier_id) matched.supplier = updateFields.supplier_id;
        updated++;
      }
    } else {
      // 2. Auto-create νέο προϊόν με ΠΛΗΡΗ defaults — όχι "undefined" σε vat/min_stock
      // Determine product type based on AI hint or fallback
      const lineProductType = (line.productType === 'longfill' || line.productType === 'shortfill' || 
                               line.productType === 'premix' || line.productType === 'concentrate') 
                              ? line.productType : 'longfill';
      // Aroma ml: από AI ή computed
      const aromaMl = line._aromaMl || line.aromaMl || _getLineAromaMl(line) || null;
      
      const newProd = {
        shop_id: SHOP_ID,
        name: (line.description || 'Νέο προϊόν').substring(0, 200),
        category: defaultCategory,
        cost: line.unitPrice || 0,
        price: Math.round((line.unitPrice || 0) * 1.4 * 100) / 100, // markup 40%
        stock: line.quantity || 0,
        min_stock: 5,
        volume_ml: line.volumeMl || null,
        shortfill_ml: aromaMl, // ml αρώματος για ΕΦΚ
        vat_rate: 24,
        supplier_id: supplierForLines ? supplierForLines.id : null,
        has_nicotine: false,
        nicotine_options: [],
        product_type: lineProductType,
        vg_pct: 70,
        pg_pct: 30,
        notes: `🤖 Δημιουργήθηκε αυτόματα από Invoice Scanner (${inv.invoiceNumber || 'no number'})`
      };
      const { data: created_prod, error } = await sb.from('products').insert(newProd).select().single();
      if(!error && created_prod){
        // Προσθήκη στο τοπικό cache στο app format (camelCase) ώστε να φαίνεται σωστά αμέσως
        if(typeof PRODUCTS !== 'undefined'){
          PRODUCTS.push({
            id: created_prod.id,
            name: created_prod.name,
            category: created_prod.category,
            cost: created_prod.cost || 0,
            price: created_prod.price || 0,
            stock: created_prod.stock || 0,
            minStock: created_prod.min_stock || 5,
            vatRate: created_prod.vat_rate || 24,
            volumeMl: created_prod.volume_ml,
            supplier: created_prod.supplier_id,
            hasNicotine: false,
            barcode: null
          });
        }
        created++;
      } else if(error){
        console.warn('[Invoice→Inventory] auto-create failed:', error.message);
      }
    }
  }

  // Toast feedback
  const parts = [];
  if(updated) parts.push(`📈 ${updated} ενημερώθηκαν`);
  if(created) parts.push(`✨ ${created} νέα`);
  if(skipped) parts.push(`⏭️ ${skipped} παραλείφθηκαν`);
  if(skippedFees) parts.push(`💸 ${skippedFees} έξοδα (όχι προϊόντα)`);
  if(parts.length > 0){
    toast(`✅ Απόθεμα: ${parts.join(' · ')}`, 'success');
  }

  // Reload products για consistency (full sync με βάση)
  try {
    if(typeof reloadProducts === 'function'){
      await reloadProducts();
    } else {
      const { data } = await sb.from('products').select('*').eq('shop_id', SHOP_ID);
      if (data) PRODUCTS = data;
    }
  } catch(e) {}
}

async function importInvoiceBoth(inv, efkAmount) {
  // Πρώτα purchases (επιστρέφει supplier_id) — μετά αποθήκη με supplier hint
  const supplierId = await importInvoiceToPurchases(inv, efkAmount);
  await importInvoiceToInventory(inv, supplierId);
}

