// ── Document numbering (localStorage per type) ──────────────────
function getNextDocNumber(type) {
  const key = 'docSeq_' + type;
  const seq = parseInt(localStorage.getItem(key) || '0') + 1;
  localStorage.setItem(key, seq);
  const prefixes = {
    invoice: 'ΤΠΥ', receipt: 'ΑΛΠ', delivery: 'ΔΑ',
    invoice_delivery: 'ΤΔΑ', credit: 'ΠΤ', offer: 'ΠΡΟ'
  };
  return (prefixes[type] || 'ΕΓΓ') + '-' + String(seq).padStart(4, '0');
}

