function renderDocuments() {
  // Load saved settings
  const saved = JSON.parse(localStorage.getItem('docSettings') || '{}');
  DOC_STATE = { ...DOC_STATE, ...saved,
    view: 'list',
    history: JSON.parse(localStorage.getItem('docHistory') || '[]'),
    platformInvoices: JSON.parse(localStorage.getItem('platformInvoices') || '[]')
  };
  _renderDocumentsPage();
}

function _renderDocumentsPage() {
  const c = document.getElementById('content');
  if (DOC_STATE.view === 'new') { _renderDocNew(); return; }
  if (DOC_STATE.view === 'preview') { _renderDocPreview(); return; }

  // ── List view ────────────────────────────────────────────────
  const hist = DOC_STATE.history.slice(0, 50);
  c.innerHTML = `
    <div class="page-head">
      <div>
        <div class="page-title">📄 Έγγραφα & Παραστατικά</div>
        <div class="page-sub">Τιμολόγια, Αποδείξεις, Δελτία Αποστολής, Προσφορές</div>
      </div>
      <div class="flex gap-2" style="flex-wrap:wrap">
        <button class="btn btn-ghost" style="min-height:44px" onclick="_openDocSettings()"><i data-lucide="settings" size="16"></i> Ρυθμίσεις</button>
        <button class="btn btn-primary" style="min-height:44px" onclick="_startNewDoc()"><i data-lucide="plus" size="16"></i> Νέο Παραστατικό</button>
      </div>
    </div>

    <!-- Quick create buttons -->
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px">
      ${INVOICE_DOC_TYPES.map(t => `
        <button onclick="DOC_STATE.type='${t.id}';_startNewDoc()" class="btn btn-ghost" style="font-size:12px;padding:10px 14px;min-height:44px;-webkit-tap-highlight-color:transparent">
          ${t.icon} ${t.label}
        </button>`).join('')}
    </div>

    <!-- Platform Invoices Section -->
    <div class="card mb-4">
      <div class="section-head">
        <div class="section-title">🧾 Τιμολόγια Πλατφορμών</div>
        <button class="btn btn-ghost" style="font-size:11px;padding:4px 10px" onclick="_openPlatformInvoiceUpload()">
          <i data-lucide="upload" size="12"></i> Ανέβασμα τιμολογίου
        </button>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;padding:16px">
        ${['efood','wolt','skroutz'].map(function(p){
          var cfg = {
            efood:{name:'e-food',emoji:'🟠',color:'#ff6b35'},
            wolt:{name:'Wolt',emoji:'🔵',color:'#009de0'},
            skroutz:{name:'Skroutz',emoji:'🟡',color:'#ff9900'}
          }[p];
          var invoices = (DOC_STATE.platformInvoices||[]).filter(function(inv){ return inv.platform===p; });
          return '<div style="border:1px solid var(--border);border-radius:10px;padding:12px;cursor:pointer" onclick="_viewPlatformInvoices(\''+p+'\')">'
            + '<div style="font-size:22px;margin-bottom:4px">'+cfg.emoji+'</div>'
            + '<div style="font-weight:700;font-size:14px">'+cfg.name+'</div>'
            + '<div style="font-size:12px;color:var(--text-2);margin-top:4px">'+invoices.length+' τιμολόγια</div>'
            + (invoices.length>0 ? '<div style="font-size:11px;color:var(--ok);margin-top:2px">Τελευταίο: '+( invoices[invoices.length-1].date||'—')+'</div>' : '')
            + '</div>';
        }).join('')}
      </div>
    </div>

    <!-- History -->
    <div class="card" style="padding:0">
      <div style="padding:16px 20px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between">
        <div class="section-title" style="font-size:14px">Εκδοθέντα Παραστατικά</div>
        ${hist.length ? `<button class="btn btn-ghost" style="font-size:11px;padding:4px 10px" onclick="_clearDocHistory()">Εκκαθάριση</button>` : ''}
      </div>
      ${hist.length === 0
        ? `<div class="muted" style="text-align:center;padding:40px">
            <div style="font-size:32px;margin-bottom:8px">📄</div>
            Δεν έχουν εκδοθεί παραστατικά ακόμα.
          </div>`
        : `<table class="tbl">
            <thead><tr>
              <th>Αριθμός</th><th>Τύπος</th><th>Πελάτης</th><th>Ημ/νία</th><th style="text-align:right">Αξία</th><th></th>
            </tr></thead>
            <tbody>
              ${hist.map(d => `<tr>
                <td class="fw-700 mono" style="font-size:13px">${d.number}</td>
                <td>${INVOICE_DOC_TYPES.find(t=>t.id===d.type)?.icon||'📄'} <span style="font-size:12px">${INVOICE_DOC_TYPES.find(t=>t.id===d.type)?.label||d.type}</span></td>
                <td style="font-size:13px">${d.clientName||'—'}</td>
                <td style="font-size:12px;color:var(--text-2)">${d.date||''}</td>
                <td style="text-align:right;font-weight:700">${eur(d.total||0)}</td>
                <td style="text-align:right">
                  <button class="btn btn-ghost" style="font-size:11px;padding:4px 10px" onclick="_reprinthDoc('${d.id}')">
                    <i data-lucide="printer" size="12"></i> Εκτύπωση
                  </button>
                </td>
              </tr>`).join('')}
            </tbody>
          </table>`
      }
    </div>
  `;
  lucide.createIcons();
}

function _startNewDoc() {
  DOC_STATE.view = 'new';
  DOC_STATE.docNumber = getNextDocNumber(DOC_STATE.type);
  DOC_STATE.docDate = today;
  DOC_STATE.lines = [{ desc:'', qty:1, unit:'τεμ', unitPrice:0, vat:24, efkMl:null }];
  DOC_STATE.clientName = DOC_STATE.clientAfm = DOC_STATE.clientDoy = DOC_STATE.clientAddr = DOC_STATE.clientCity = '';
  DOC_STATE.notes = '';
  _renderDocNew();
}

