  if(PURCHASES_FILTER_MONTH) filtered = filtered.filter(p=>(p.purchase_date||'').startsWith(PURCHASES_FILTER_MONTH));

  // Σύνολα
  const totalNet = filtered.reduce((a,b)=>a+parseFloat(b.net_amount||0),0);
  const totalVAT = filtered.reduce((a,b)=>a+parseFloat(b.vat_amount||0),0);
  const totalGross = filtered.reduce((a,b)=>a+parseFloat(b.gross_amount||0),0);

