function _auditConfirmStart(type){
  const inspectorName = (document.getElementById('auditInspectorName')?.value || '').trim();
  const authority = (document.getElementById('auditAuthority')?.value || '').trim();
  const fullName = inspectorName + (authority ? ` (${authority})` : '');
  if(typeof closeModal === 'function') closeModal();
  _auditStartDirect(type, fullName);
}

async function _auditStartDirect(type, inspectorName){
  AUDIT_STATE = {
    active: true,
    type: type,
    inspectorName: inspectorName || '',
    startedAt: new Date().toISOString(),
    endedAt: null,
    exitPin: (typeof getAdminPin === 'function') ? getAdminPin() : '2510',
    shownSections: [],
    exportCount: 0
  };

  // Log to Supabase (async, μη blocking)
  try{
    if(typeof sb !== 'undefined'){
      await sb.from('inspector_logs').insert({
        action: 'audit_start',
        details: {
          type: type,
          inspector: inspectorName,
          started: AUDIT_STATE.startedAt
        }
      });
    }
  }catch(e){ console.warn('audit log failed:', e); }

  if(typeof toast === 'function') toast('🛡️ Audit Mode ενεργό', 'success');

  // Render lock screen
  renderAuditLockScreen();
}


