/* ── 5. RENDER SECTIONS ──────────────────────────────────────────────── */

async function renderAuditSections(type){
  const cfg = AUDIT_TYPES[type];
  if(!cfg) return;
  const container = document.getElementById('auditSections');
  if(!container) return;
  const isEl = (typeof LANG === 'undefined' || LANG === 'el');

  // Render section cards
  container.innerHTML = cfg.sections.map(secKey => `
    <div class="audit-section" data-section="${secKey}" style="
      background:var(--bg-2);
      border:1px solid var(--border);
      border-radius:14px;
      padding:16px;
      margin-bottom:14px;
    ">
      <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:12px;">
        <h3 style="margin:0;font-size:16px;font-weight:700;">
          ${SECTION_LABELS[secKey]?.[isEl?'el':'en'] || secKey}
        </h3>
        <div class="audit-sec-status" style="font-size:11px;color:var(--text-2);">⏳</div>
      </div>
      <div class="audit-sec-body" style="font-size:13px;line-height:1.5;">
        ${isEl?'Φόρτωση...':'Loading...'}
      </div>
    </div>
  `).join('');

  // Load each section
  for(const secKey of cfg.sections){
    const card = container.querySelector(`[data-section="${secKey}"]`);
    if(!card) continue;
    try{
      const html = await renderSectionContent(secKey);
      card.querySelector('.audit-sec-body').innerHTML = html;
      card.querySelector('.audit-sec-status').textContent = '✅';
      card.querySelector('.audit-sec-status').style.color = 'var(--ok)';
      AUDIT_STATE.shownSections.push(secKey);
    }catch(err){
      console.error('Section load failed:', secKey, err);
      card.querySelector('.audit-sec-body').innerHTML = `
        <div style="color:var(--danger);font-size:12px;">
          ⚠️ ${isEl?'Σφάλμα φόρτωσης':'Load error'}: ${escapeHtml(err.message||'')}
        </div>`;
      card.querySelector('.audit-sec-status').textContent = '⚠️';
    }
  }
}


/* ── 6. SECTION RENDERERS ────────────────────────────────────────────── */

async function renderSectionContent(secKey){
  switch(secKey){
    case 'efk_summary':         return await _secEfkSummary();
    case 'batches_invoices':    return await _secBatchesInvoices();
    case 'mydata_links':        return await _secMyDataLinks();
    case 'license':             return _secLicense();
    case 'products_compliance': return await _secProductsCompliance();
    case 'coa_docs':            return await _secCoaDocs();
    case 'tpd_docs':            return await _secTpdDocs();
    case 'euceg_register':      return await _secEucegRegister();
    case 'expiry_alerts':       return await _secExpiryAlerts();
    case 'minor_protection':    return _secMinorProtection();
    case 'sales_log':           return await _secSalesLog();
    default: return '<i>—</i>';
  }
}

// ── 6.1 EFK Summary (Calculator) ─────────────────────────────────────
async function _secEfkSummary(){
  const isEl = (typeof LANG === 'undefined' || LANG === 'el');
  // Φόρτωσε batches και υπολόγισε ΕΦΚ
  let batches = [];
  try{
    const {data} = await sb.from('batches').select('*').order('received_date',{ascending:false}).limit(500);
    batches = data || [];
  }catch(e){}

  // Filter μόνο υγρά (αν υπάρχει product με ml > 0)
  const products = (typeof PRODUCTS !== 'undefined') ? PRODUCTS : [];
  const productMap = {};
  products.forEach(p => productMap[p.id] = p);

  const liquidBatches = batches.filter(b => {
    const p = productMap[b.product_id];
    return p && (p.ml > 0 || (p.category||'').toLowerCase().includes('υγρ'));
  });

  let totalMl = 0;
  let totalEfk = 0;
  let unpaidEfk = 0;
  liquidBatches.forEach(b => {
    const p = productMap[b.product_id];
    const ml = (p?.ml || 0) * (b.initial_qty || 0);
    totalMl += ml;
    totalEfk += ml * AUDIT_EFK_RATE;
    if(!b.efk_paid) unpaidEfk += ml * AUDIT_EFK_RATE;
  });

  return `
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-bottom:12px;">
      <div style="background:var(--bg-3);padding:12px;border-radius:10px;">
        <div style="font-size:11px;color:var(--text-2);text-transform:uppercase;letter-spacing:1px;">${isEl?'Σύνολο ml':'Total ml'}</div>
        <div style="font-size:22px;font-weight:800;color:var(--accent);">${totalMl.toLocaleString('el-GR')}</div>
      </div>
      <div style="background:var(--bg-3);padding:12px;border-radius:10px;">
        <div style="font-size:11px;color:var(--text-2);text-transform:uppercase;letter-spacing:1px;">${isEl?'ΕΦΚ Σύνολο':'Total Excise'}</div>
        <div style="font-size:22px;font-weight:800;">${totalEfk.toFixed(2)}€</div>
      </div>
      <div style="background:var(--bg-3);padding:12px;border-radius:10px;">
        <div style="font-size:11px;color:var(--text-2);text-transform:uppercase;letter-spacing:1px;">${isEl?'Παρτίδες':'Batches'}</div>
        <div style="font-size:22px;font-weight:800;">${liquidBatches.length}</div>
      </div>
    </div>
    <div style="font-size:12px;color:var(--text-1);line-height:1.5;background:rgba(74,163,255,0.08);padding:10px;border-radius:8px;">
      <b>📜 ${isEl?'Νομική βάση':'Legal basis'}:</b>
      ${isEl
        ? 'Νόμος 4389/2016 — ΕΦΚ €0.10/ml για υγρά αναπλήρωσης ηλεκτρονικού τσιγάρου. Δηλώνεται με Δήλωση ΕΦΚ στις τελωνειακές αρχές.'
        : 'Law 4389/2016 — Excise tax €0.10/ml on e-cigarette refill liquids. Declared via ΕΦΚ Declaration to customs authorities.'}
    </div>
  `;
}

// ── 6.2 Batches & Invoices ───────────────────────────────────────────
async function _secBatchesInvoices(){
  const isEl = (typeof LANG === 'undefined' || LANG === 'el');
  let batches = [];
  let suppliers = [];
  try{
    const [b,s] = await Promise.all([
      sb.from('batches').select('*').order('received_date',{ascending:false}).limit(50),
      sb.from('suppliers').select('id,name')
    ]);
    batches = b.data || [];
    suppliers = s.data || [];
  }catch(e){ throw e; }

  const supMap = {};
  suppliers.forEach(s => supMap[s.id] = s.name);
  const products = (typeof PRODUCTS !== 'undefined') ? PRODUCTS : [];
  const prodMap = {};
  products.forEach(p => prodMap[p.id] = p);

  if(batches.length === 0){
    return `<div style="color:var(--text-2);font-size:13px;">${isEl?'Δεν υπάρχουν παρτίδες.':'No batches.'}</div>`;
  }

  return `
    <div style="overflow-x:auto;-webkit-overflow-scrolling:touch;">
      <table style="width:100%;font-size:12px;border-collapse:collapse;min-width:600px;">
        <thead>
          <tr style="border-bottom:1px solid var(--border);text-align:left;">
            <th style="padding:8px;">${isEl?'Παρτίδα':'Lot'}</th>
            <th style="padding:8px;">${isEl?'Προϊόν':'Product'}</th>
            <th style="padding:8px;">${isEl?'Προμηθευτής':'Supplier'}</th>
            <th style="padding:8px;">${isEl?'Παραλαβή':'Received'}</th>
            <th style="padding:8px;">${isEl?'Λήξη':'Expiry'}</th>
            <th style="padding:8px;text-align:right;">${isEl?'Τεμ.':'Qty'}</th>
          </tr>
        </thead>
        <tbody>
          ${batches.slice(0,30).map(b => `
            <tr style="border-bottom:1px solid var(--border);">
              <td style="padding:8px;font-family:'JetBrains Mono',monospace;">${escapeHtml(b.lot_number||'—')}</td>
              <td style="padding:8px;">${escapeHtml(prodMap[b.product_id]?.name||'—')}</td>
              <td style="padding:8px;">${escapeHtml(supMap[b.supplier_id]||'—')}</td>
              <td style="padding:8px;">${b.received_date||'—'}</td>
              <td style="padding:8px;">${b.expiry_date||'—'}</td>
              <td style="padding:8px;text-align:right;">${b.initial_qty||0}</td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    </div>
    ${batches.length > 30 ? `<div style="font-size:11px;color:var(--text-2);margin-top:8px;">${isEl?'+ ' + (batches.length-30) + ' ακόμα':'+ ' + (batches.length-30) + ' more'}</div>` : ''}
  `;
}

