// ── 6.8 Expiry Alerts ─────────────────────────────────────────────────
async function _secExpiryAlerts(){
  const isEl = (typeof LANG === 'undefined' || LANG === 'el');
  const today = new Date();
  const in30 = new Date(today.getTime() + 30*86400000);

  let batches = [];
  let docs = [];
  try{
    const [b,d] = await Promise.all([
      sb.from('batches').select('*').not('expiry_date','is',null),
      sb.from('product_documents').select('*').not('expires_at','is',null)
    ]);
    batches = b.data || [];
    docs = d.data || [];
  }catch(e){}

  const expiringBatches = batches.filter(b => {
    const exp = new Date(b.expiry_date);
    return exp <= in30;
  });
  const expiringDocs = docs.filter(d => {
    const exp = new Date(d.expires_at);
    return exp <= in30;
  });

  if(expiringBatches.length === 0 && expiringDocs.length === 0){
    return `<div style="color:var(--ok);font-size:13px;">✅ ${isEl?'Καμία λήξη μέσα στις επόμενες 30 ημέρες.':'No expirations in the next 30 days.'}</div>`;
  }

  return `
    ${expiringBatches.length > 0 ? `
      <div style="margin-bottom:10px;">
        <b style="color:var(--warn);">⚠️ ${isEl?'Παρτίδες που λήγουν':'Batches expiring'}:</b> ${expiringBatches.length}
      </div>
    ` : ''}
    ${expiringDocs.length > 0 ? `
      <div>
        <b style="color:var(--warn);">⚠️ ${isEl?'Έγγραφα που λήγουν':'Documents expiring'}:</b> ${expiringDocs.length}
      </div>
    ` : ''}
  `;
}

