/* ── 7. SEARCH ───────────────────────────────────────────────────────── */

var _auditSearchTimer = null;
function auditSearchHandler(query){
  clearTimeout(_auditSearchTimer);
  _auditSearchTimer = setTimeout(() => _auditDoSearch(query), 280);
}

async function _auditDoSearch(query){
  const container = document.getElementById('auditSearchResults');
  if(!container) return;
  const isEl = (typeof LANG === 'undefined' || LANG === 'el');
  query = (query||'').trim();
  if(query.length < 2){ container.innerHTML = ''; return; }

  container.innerHTML = `<div style="color:var(--text-2);font-size:12px;padding:8px;">${isEl?'⏳ Αναζήτηση...':'⏳ Searching...'}</div>`;

  const products = (typeof PRODUCTS !== 'undefined') ? PRODUCTS : [];
  const q = query.toLowerCase();

  // Search products by name/barcode
  const matchProducts = products.filter(p =>
    (p.name||'').toLowerCase().includes(q) ||
    (p.barcode||'').toLowerCase().includes(q)
  ).slice(0,5);

  // Search batches by lot
  let matchBatches = [];
  try{
    const {data} = await sb.from('batches').select('*').ilike('lot_number', `%${query}%`).limit(5);
    matchBatches = data || [];
  }catch(e){}

  if(matchProducts.length === 0 && matchBatches.length === 0){
    container.innerHTML = `<div style="color:var(--text-2);font-size:12px;padding:8px;background:var(--bg-2);border-radius:8px;">${isEl?'Δεν βρέθηκε τίποτα':'No matches'}</div>`;
    return;
  }

  container.innerHTML = `
    <div style="background:var(--bg-2);border:1px solid var(--accent);border-radius:10px;padding:12px;">
      <div style="font-size:12px;color:var(--text-1);margin-bottom:8px;">
        🔍 ${isEl?'Αποτελέσματα':'Results'}: <b>${matchProducts.length + matchBatches.length}</b>
      </div>
      ${matchProducts.map(p => `
        <div style="background:var(--bg-3);padding:8px 10px;border-radius:8px;margin-bottom:6px;">
          <div style="font-weight:600;font-size:13px;">📦 ${escapeHtml(p.name||'')}</div>
          <div style="font-size:11px;color:var(--text-2);font-family:monospace;">${escapeHtml(p.barcode||'—')} • ${p.ml||0}ml</div>
        </div>
      `).join('')}
      ${matchBatches.map(b => `
        <div style="background:var(--bg-3);padding:8px 10px;border-radius:8px;margin-bottom:6px;">
          <div style="font-weight:600;font-size:13px;">🏷️ ${isEl?'Παρτίδα':'Batch'}: ${escapeHtml(b.lot_number||'')}</div>
          <div style="font-size:11px;color:var(--text-2);">${b.received_date||''} → ${b.expiry_date||'—'}</div>
        </div>
      `).join('')}
    </div>
  `;
}


/* ── 8. EXPORT ZIP ───────────────────────────────────────────────────── */

async function auditExportZip(){
  const isEl = (typeof LANG === 'undefined' || LANG === 'el');
  if(typeof toast==='function') toast(isEl?'📦 Δημιουργία πακέτου...':'📦 Creating package...','info');

  try{
    if(typeof window.jspdf === 'undefined' && typeof jsPDF === 'undefined'){
      throw new Error('jsPDF not loaded');
    }
    const {jsPDF} = window.jspdf || {jsPDF: window.jsPDF};
    const doc = new jsPDF();

    // Header
    doc.setFontSize(20);
    doc.setFont(undefined, 'bold');
    doc.text('ZyroNex ZyroNex — AUDIT REPORT', 105, 20, {align:'center'});
    doc.setFontSize(10);
    doc.setFont(undefined, 'normal');
    doc.text(`Type: ${AUDIT_TYPES[AUDIT_STATE.type]?.label_en || AUDIT_STATE.type}`, 105, 28, {align:'center'});
    doc.text(`Started: ${AUDIT_STATE.startedAt}`, 105, 34, {align:'center'});
    if(AUDIT_STATE.inspectorName){
      doc.text(`Inspector: ${AUDIT_STATE.inspectorName}`, 105, 40, {align:'center'});
    }

    let y = 55;
    doc.setFontSize(12);
    doc.setFont(undefined, 'bold');
    doc.text('SECTIONS INCLUDED:', 14, y); y+=8;
    doc.setFont(undefined, 'normal');
    doc.setFontSize(10);
    AUDIT_STATE.shownSections.forEach(sec => {
      doc.text(`• ${SECTION_LABELS[sec]?.en || sec}`, 18, y);
      y+=6;
    });

    // EFK summary table
    y+=10;
    doc.setFontSize(12);
    doc.setFont(undefined,'bold');
    doc.text('BATCHES (last 50)', 14, y); y+=4;

    try{
      const {data: batches} = await sb.from('batches').select('*').order('received_date',{ascending:false}).limit(50);
      const products = (typeof PRODUCTS !== 'undefined') ? PRODUCTS : [];
      const prodMap = {};
      products.forEach(p => prodMap[p.id] = p);

      if(doc.autoTable && batches){
        doc.autoTable({
          startY: y+2,
          head: [['Lot','Product','Received','Expiry','Qty']],
          body: batches.slice(0,40).map(b => [
            b.lot_number||'—',
            prodMap[b.product_id]?.name || '—',
            b.received_date||'—',
            b.expiry_date||'—',
            b.initial_qty||0
          ]),
          styles: {fontSize:8},
          headStyles: {fillColor:[0,168,132]}
        });
      }
    }catch(e){ console.warn(e); }

    // Footer
    const pages = doc.internal.getNumberOfPages();
    for(let i=1;i<=pages;i++){
      doc.setPage(i);
      doc.setFontSize(8);
      doc.setTextColor(120);
      doc.text(`Page ${i}/${pages} • Generated by ZyroNex ZyroNex`, 105, 290, {align:'center'});
      doc.setTextColor(235,235,235);
      doc.setFontSize(42);
      doc.text('ZyroNex', 105, 160, {align:'center', angle:45});
      doc.setTextColor(120);
      doc.setFontSize(8);
    }

    const filename = `audit_${AUDIT_STATE.type}_${(new Date()).toISOString().slice(0,10)}.pdf`;
    doc.save(filename);

    AUDIT_STATE.exportCount++;

    // Log
    try{
      await sb.from('inspector_logs').insert({
        action: 'audit_export',
        details: { type: AUDIT_STATE.type, filename }
      });
    }catch(e){}

    if(typeof toast==='function') toast(isEl?'✅ PDF δημιουργήθηκε':'✅ PDF created','success');
  }catch(err){
    console.error(err);
    if(typeof toast==='function') toast((isEl?'Σφάλμα: ':'Error: ') + err.message,'danger');
  }
}


/* ── 9. AI SUMMARY (Premium) ─────────────────────────────────────────── */

async function auditAiSummary(){
  if(typeof askClaude !== 'function'){
    if(typeof toast==='function') toast('AI not available','warning');
    return;
  }
  const isEl = (typeof LANG === 'undefined' || LANG === 'el');

  if(typeof openModal === 'function'){
    openModal(`
      <h2 style="margin-top:0;">🤖 ${isEl?'ZyroNex Σύνοψη ✨ Audit':'AI Audit Summary'}</h2>
      <div id="aiSummaryBody" style="font-size:13px;line-height:1.6;color:var(--text-1);">
        ⏳ ${isEl?'Δημιουργία σύνοψης...':'Generating summary...'}
      </div>
    `);
  }

  try{
    const cfg = AUDIT_TYPES[AUDIT_STATE.type];
    const ctxPrompt = isEl
      ? `Είσαι ειδικός σε ελληνικούς νόμους για vape. Δώσε σύντομη σύνοψη (max 200 λέξεις) για audit ${cfg.label_el}. Sections που εμφανίστηκαν: ${AUDIT_STATE.shownSections.join(', ')}. Πες πιθανά κενά συμμόρφωσης βάσει ν.4419/2016, ν.5216/2025, ν.4389/2016.`
      : `You are an expert in Greek vape regulations. Provide a brief summary (max 200 words) for ${cfg.label_en} audit. Sections shown: ${AUDIT_STATE.shownSections.join(', ')}. Identify potential compliance gaps per Greek laws 4419/2016, 5216/2025, 4389/2016.`;

    const res = await askClaude([{role:'user', content: ctxPrompt}], '');
    const body = document.getElementById('aiSummaryBody');
    if(body) body.innerHTML = (res||'').replace(/\n/g,'<br>');
  }catch(err){
    const body = document.getElementById('aiSummaryBody');
    if(body) body.innerHTML = `<span style="color:var(--danger);">Error: ${escapeHtml(err.message)}</span>`;
  }
}


