function _auditExitPinPress(digit){
  if(!window._auditExitPinBuffer) window._auditExitPinBuffer = '';
  if(window._auditExitPinBuffer.length >= 4) return;
  window._auditExitPinBuffer += digit;
  _auditExitPinUpdateDots();
  // Auto-submit όταν συμπληρωθούν 4 ψηφία
  if(window._auditExitPinBuffer.length === 4){
    setTimeout(()=>_auditExitConfirm(window._auditExitPinBuffer), 180);
  }
}

function _auditExitPinBackspace(){
  if(!window._auditExitPinBuffer) return;
  window._auditExitPinBuffer = window._auditExitPinBuffer.slice(0,-1);
  _auditExitPinUpdateDots();
}

function _auditExitPinClear(){
  window._auditExitPinBuffer = '';
  _auditExitPinUpdateDots();
  const err = document.getElementById('auditExitErr');
  if(err){ err.textContent=''; err.style.opacity='0'; }
}

function _auditExitPinUpdateDots(){
  const len = (window._auditExitPinBuffer||'').length;
  document.querySelectorAll('.audit-pin-dot').forEach((dot,i)=>{
    if(i < len) dot.classList.add('filled');
    else dot.classList.remove('filled');
  });
}

async function _auditExitConfirm(pin){
  const isEl = (typeof LANG === 'undefined' || LANG === 'el');
  if(pin !== AUDIT_STATE.exitPin){
    const err = document.getElementById('auditExitErr');
    const dotsContainer = document.getElementById('auditExitPinDots');
    if(err){
      err.textContent = isEl?'❌ Λάθος PIN':'❌ Wrong PIN';
      err.style.opacity = '1';
    }
    if(dotsContainer){
      dotsContainer.classList.add('audit-pin-shake');
      setTimeout(()=>dotsContainer.classList.remove('audit-pin-shake'), 450);
    }
    // Clear το buffer για νέα προσπάθεια
    setTimeout(()=>{
      window._auditExitPinBuffer = '';
      _auditExitPinUpdateDots();
    }, 500);
    return;
  }

  AUDIT_STATE.endedAt = new Date().toISOString();

  try{
    await sb.from('inspector_logs').insert({
      action: 'audit_end',
      details: {
        type: AUDIT_STATE.type,
        inspector: AUDIT_STATE.inspectorName,
        started: AUDIT_STATE.startedAt,
        ended: AUDIT_STATE.endedAt,
        sections_shown: AUDIT_STATE.shownSections,
        exports: AUDIT_STATE.exportCount
      }
    });
  }catch(e){}

  AUDIT_STATE = { active:false, type:null, inspectorName:'', startedAt:null, endedAt:null, exitPin:null, shownSections:[], exportCount:0 };
  window._auditExitPinBuffer = '';

  document.body.classList.remove('audit-mode-active');
  if(typeof closeModal === 'function') closeModal();
  if(typeof toast === 'function') toast(isEl?'🔓 Έξοδος από Audit Mode':'🔓 Exited Audit Mode','success');

  // Επιστρέφουμε στη σελίδα audit (όχι στο dashboard)
  if(typeof renderPage === 'function') renderPage('audit');
  else renderAuditVault();
}


/* ── 11. HISTORY ─────────────────────────────────────────────────────── */

async function loadAuditHistory(){
  const container = document.getElementById('auditHistoryContainer');
  if(!container) return;
  const isEl = (typeof LANG === 'undefined' || LANG === 'el');

  try{
    const {data} = await sb.from('inspector_logs')
      .select('*')
      .in('action',['audit_start','audit_end','audit_export'])
      .order('created_at',{ascending:false})
      .limit(20);

    if(!data || data.length === 0){
      container.innerHTML = `<div style="text-align:center;padding:18px;color:var(--text-2);font-size:13px;">${isEl?'Κανένα προηγούμενο audit ακόμα.':'No previous audits yet.'}</div>`;
      return;
    }

    container.innerHTML = data.slice(0,8).map(log => {
      const det = log.details || {};
      const action = log.action.replace('audit_','').toUpperCase();
      const date = new Date(log.created_at).toLocaleString(isEl?'el-GR':'en-GB');
      return `
        <div style="display:flex;justify-content:space-between;padding:8px 10px;border-bottom:1px solid var(--border);font-size:12px;flex-wrap:wrap;gap:6px;">
          <div>
            <span style="font-weight:600;color:var(--accent);">${action}</span>
            ${det.type?` • ${AUDIT_TYPES[det.type]?.[isEl?'label_el':'label_en'] || det.type}`:''}
          </div>
          <div style="color:var(--text-2);">${date}</div>
        </div>
      `;
    }).join('');
  }catch(err){
    container.innerHTML = `<div style="color:var(--text-2);font-size:12px;text-align:center;padding:14px;">${isEl?'Δεν φορτώθηκε ιστορικό.':'History not loaded.'}</div>`;
  }
}


/* ── 12. UTILS ───────────────────────────────────────────────────────── */

function escapeHtml(s){
  if(s == null) return '';
  return String(s)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

function _isExpiringSoon(dateStr){
  if(!dateStr) return false;
  const d = new Date(dateStr);
  const today = new Date();
  const diff = (d - today) / 86400000;
  return diff >= 0 && diff <= 30;
}

function _injectAuditCSS(){
  if(document.getElementById('auditModeCSS')) return;
  const css = document.createElement('style');
  css.id = 'auditModeCSS';
  css.textContent = `
    /* Audit Mode — hide non-essential UI for inspector clarity */
    body.audit-mode-active .sidebar { display:none !important; }
    body.audit-mode-active .topbar,
    body.audit-mode-active .topbar-actions,
    body.audit-mode-active #brainPanel,
    body.audit-mode-active .nav-section,
    body.audit-mode-active .ai-panel { display:none !important; }
    body.audit-mode-active .app { grid-template-columns:1fr !important; }
    body.audit-mode-active .main-content { padding:16px !important; }

    /* Hide sensitive data classes (αν τα έχεις) */
    body.audit-mode-active .customer-personal-data,
    body.audit-mode-active .profit-margin,
    body.audit-mode-active .cost-price,
    body.audit-mode-active .marketing-data { filter:blur(8px); pointer-events:none; }

    /* Mobile fixes for audit mode */
    @media (max-width: 720px){
      body.audit-mode-active .audit-header { flex-wrap:wrap; }
      body.audit-mode-active .audit-type-card { min-height:120px; }
    }

    /* iOS Safari specific */
    body.audit-mode-active input,
    body.audit-mode-active button {
      -webkit-tap-highlight-color: rgba(0,212,168,0.2);
    }
  `;
  document.head.appendChild(css);
}


