// --- plugin-market/tools sub-module ---
var PLUGIN_SUB = {
  ALERT_WARN:     10,
  ALERT_URGENT:    5,
  GRACE_READONLY:  3,
  GRACE_SUSPEND:   7,
};

// Returns the billing record for a plugin. Prefers the authoritative DB cache;
// falls back to localStorage only if the DB hasn't loaded yet.
function _pluginBilling(pluginId){
  // DB cache (authoritative)
  if (PLUGIN_SUBS_CACHE && PLUGIN_SUBS_CACHE[pluginId]) {
    var r = PLUGIN_SUBS_CACHE[pluginId];
    return {
      mode: r.mode,
      status: r.status === 'canceled' ? 'cancelled' : r.status, // normalize spelling
      expiresAt: r.current_period_end || null,
      cancelAtPeriodEnd: r.cancel_at_period_end
    };
  }
  // Fallback: localStorage (offline / pre-load)
  try {
    var map = JSON.parse(localStorage.getItem('zn_plugin_billing') || '{}');
    return map[pluginId] || null;
  } catch(_) { return null; }
}

// Days left until (or overdue past) a plugin's renewal date. null = no expiry set.
function getPluginDaysLeft(pluginId){
  var b = _pluginBilling(pluginId);
  if (!b) return null;
  // One-time purchases never expire.
  if (b.mode === 'oneTime' || b.mode === 'once') return null;
  if (!b.expiresAt) return null;
  return Math.floor((new Date(b.expiresAt) - Date.now()) / 86400000);
}

// State machine, identical in spirit to getSubState() for the app.
function getPluginState(pluginId){
  // Owner always sees plugins as active.
  try { if (_isOwnerBypass()) return 'active'; } catch(_) {}
  var b = _pluginBilling(pluginId);
  if (!b) return 'active'; // installed without billing info → treat as active
  if (b.status === 'cancelled' || b.status === 'canceled') return 'cancelled';
  // Stripe-reported past_due is authoritative regardless of local dates.
  if (b.status === 'past_due') {
    var dlp = getPluginDaysLeft(pluginId);
    if (dlp !== null && dlp < 0 && Math.abs(dlp) >= PLUGIN_SUB.GRACE_SUSPEND) return 'suspended';
    if (dlp !== null && dlp < 0 && Math.abs(dlp) >= PLUGIN_SUB.GRACE_READONLY) return 'readonly';
    return 'past_due';
  }
  var dl = getPluginDaysLeft(pluginId);
  if (dl === null) return 'active'; // one-time or no expiry
  if (dl < 0) {
    var od = Math.abs(dl);
    if (od >= PLUGIN_SUB.GRACE_SUSPEND)  return 'suspended';
    if (od >= PLUGIN_SUB.GRACE_READONLY) return 'readonly';
    return 'past_due';
  }
  if (dl <= PLUGIN_SUB.ALERT_URGENT) return 'urgent';
  if (dl <= PLUGIN_SUB.ALERT_WARN)   return 'warning';
  return 'active';
}

// Is the plugin currently usable (visible & functional)? readonly still usable.
// Δείχνει/κρύβει nav items που είναι κλειδωμένα πίσω από plugin.
// Ο owner (perms='*') τα βλέπει ΟΛΑ χωρίς χρέωση μέσω isPluginActive→_isOwnerBypass.
function _applyPluginGates(){
  try{
    document.querySelectorAll('[data-plugin-gated]').forEach(function(el){
      var pid = el.getAttribute('data-plugin-gated');
      el.style.display = isPluginActive(pid) ? '' : 'none';
    });
  }catch(_){}
}
function refreshNav(){ _applyPluginGates(); }
function setPluginInstalled(pluginId, install){
  try {
    var list = getInstalledPlugins();
    var i = list.indexOf(pluginId);
    if (install && i === -1) list.push(pluginId);
    else if (!install && i !== -1) list.splice(i, 1);
    localStorage.setItem(_pluginStoreKey(), JSON.stringify(list));
    return true;
  } catch(_) { return false; }
}

// ── Plan feature check ───────────────────────────────────────────────────────
// ΠΡΟΣΟΧΗ: Ο admin/owner (perms='*') ΠΑΝΤΑ έχει access σε όλα τα features,
// ανεξάρτητα από το plan. Έτσι οι developers/owners δεν βλέπουν paywalls.
function _isOwnerBypass(){
  // Test Mode: ο owner μπορεί προσωρινά να "δει" την app σαν απλός πελάτης,
  // για να δοκιμάσει αγορές/κλειδώματα plugins. Δεν αλλάζει δικαιώματα διαχείρισης.
  if (typeof window !== 'undefined' && window.ZN_TEST_AS_CUSTOMER === true) return false;
  return typeof CURRENT_USER !== 'undefined' 
    && CURRENT_USER 
    && Array.isArray(CURRENT_USER.perms) 
    && CURRENT_USER.perms.includes('*');
}

// ── TEST MODE: δες την app σαν απλός πελάτης (μόνο για owner) ──
// Persist στο localStorage ώστε να επιβιώνει σε navigation/refresh.
try { window.ZN_TEST_AS_CUSTOMER = (localStorage.getItem('zn_test_as_customer') === '1'); } catch(_) { window.ZN_TEST_AS_CUSTOMER = false; }

function znToggleTestMode(){
  window.ZN_TEST_AS_CUSTOMER = !window.ZN_TEST_AS_CUSTOMER;
  try { localStorage.setItem('zn_test_as_customer', window.ZN_TEST_AS_CUSTOMER ? '1' : '0'); } catch(_){}
  if (window.ZN_TEST_AS_CUSTOMER) {
    if (typeof toast === 'function') toast('🛍️ Test Mode ΕΝΕΡΓΟ — βλέπεις την app σαν πελάτης. Τα plugins είναι πλέον κλειδωμένα/αγοράσιμα.', 'info');
  } else {
    if (typeof toast === 'function') toast('👑 Επέστρεψες σε λειτουργία owner — όλα ξεκλείδωτα.', 'success');
  }
  // Re-load plugin subscriptions & refresh gates/UI για να φανεί η αλλαγή αμέσως.
  try { if (typeof loadPluginSubscriptions === 'function') loadPluginSubscriptions(); } catch(_){}
  try { if (typeof _applyPluginGates === 'function') _applyPluginGates(); } catch(_){}
  try { if (typeof renderSettings === 'function') renderSettings(); } catch(_){}
}
window.znToggleTestMode = znToggleTestMode;

// --- expense-calendar sub-module (data layer) ---
var EXPENSE_CALENDAR = {
  CACHE: { calendar: [], payments: [], lastFetch: 0 },
  RECEIPT_BUCKET: 'expense-receipts',
  
  DEFAULT_PRESETS: [
    { name: 'Ενοίκιο', category: 'rent', frequency: 'monthly', day_of_month: 5, default_amount: null, is_variable: false, cashbook_category: 'Ενοίκιο', icon: '🏠' },
    { name: 'ΔΕΗ', category: 'utilities', frequency: 'bimonthly', day_of_month: 20, default_amount: null, is_variable: true, cashbook_category: 'ΔΕΗ', icon: '⚡' },
    { name: 'Ύδρευση', category: 'utilities', frequency: 'quarterly', day_of_month: 15, default_amount: null, is_variable: true, cashbook_category: 'Νερό', icon: '💧' },
    { name: 'Τηλέφωνο/Internet', category: 'utilities', frequency: 'monthly', day_of_month: 25, default_amount: null, is_variable: false, cashbook_category: 'Τηλεπικοινωνίες', icon: '📞' },
    { name: 'ΕΦΚΑ', category: 'social_security', frequency: 'monthly', day_of_month: 28, default_amount: null, is_variable: false, cashbook_category: 'ΕΦΚΑ', icon: '👥' },
    { name: 'Λογιστής', category: 'professional', frequency: 'monthly', day_of_month: 10, default_amount: null, is_variable: false, cashbook_category: 'Λογιστικά', icon: '📊' },
    { name: 'Ένσημα Προσωπικού', category: 'social_security', frequency: 'monthly', day_of_month: 15, default_amount: null, is_variable: true, cashbook_category: 'Ένσημα', icon: '🧾' },
    { name: 'ΦΠΑ Τριμήνου', category: 'tax', frequency: 'quarterly', day_of_month: 25, default_amount: null, is_variable: true, cashbook_category: 'ΦΠΑ', icon: '💼' }
  ],
  
  CATEGORY_LABELS: {
    rent: { el: 'Ενοίκιο', icon: '🏠' },
    utilities: { el: 'Λογαριασμοί', icon: '⚡' },
    social_security: { el: 'Ασφαλιστικά', icon: '👥' },
    tax: { el: 'Φόροι', icon: '💼' },
    professional: { el: 'Επαγγελματικά', icon: '📊' },
    insurance: { el: 'Ασφάλιστρα', icon: '🛡️' },
    other: { el: 'Άλλα', icon: '📌' }
  },
  
  FREQUENCY_LABELS: {
    monthly: 'Μηνιαία',
    bimonthly: 'Διμηνιαία',
    quarterly: 'Τριμηνιαία',
    yearly: 'Ετήσια',
    oneoff: 'Μία φορά'
  },
  
  async load(){
    try{
      const [calRes, payRes] = await Promise.all([
        sb.from('expense_calendar').select('*').eq('shop_id', SHOP_ID).eq('is_active', true).order('day_of_month', { ascending: true }),
        sb.from('expense_payments').select('*').eq('shop_id', SHOP_ID).order('due_date', { ascending: false }).limit(500)
      ]);
      this.CACHE.calendar = calRes.data || [];
      this.CACHE.payments = payRes.data || [];
      this.CACHE.lastFetch = Date.now();
      await this._generateUpcomingPayments();
      return true;
    }catch(e){
      console.error('[ExpenseCalendar] load error:', e);
      return false;
    }
  },
  
  async _generateUpcomingPayments(){
    const now = new Date();
    const toCreate = [];
    for(const cal of this.CACHE.calendar){
      const nextDue = this._calculateNextDueDate(cal, now);
      if(!nextDue) continue;
      const exists = this.CACHE.payments.some(p => 
        p.expense_calendar_id === cal.id && 
        p.due_date === this._formatDate(nextDue) &&
        p.status !== 'skipped'
      );
      if(exists) continue;
      toCreate.push({
        shop_id: SHOP_ID,
        expense_calendar_id: cal.id,
        due_date: this._formatDate(nextDue),
        status: 'pending'
      });
    }
    if(toCreate.length > 0){
      try{
        const { data, error } = await sb.from('expense_payments').insert(toCreate).select();
        if(!error && data) this.CACHE.payments = [...this.CACHE.payments, ...data];
      }catch(e){ console.warn('[ExpenseCalendar] auto-create:', e); }
    }
  },
  
  _calculateNextDueDate(cal, fromDate){
    if(!cal.frequency || !cal.day_of_month) return null;
    const now = new Date(fromDate);
    const day = Math.min(cal.day_of_month, 28);
    
    if(cal.frequency === 'oneoff'){
      const start = new Date(cal.start_date);
      return start >= now ? start : null;
    }
    
    const startDate = cal.start_date ? new Date(cal.start_date) : now;
    let candidate = new Date(now.getFullYear(), now.getMonth(), day);
    const monthStep = { monthly: 1, bimonthly: 2, quarterly: 3, yearly: 12 }[cal.frequency] || 1;
    
    if(candidate < now){
      candidate.setMonth(candidate.getMonth() + monthStep);
    } else if(monthStep > 1){
      const monthsSinceStart = (candidate.getFullYear() - startDate.getFullYear()) * 12 
                              + (candidate.getMonth() - startDate.getMonth());
      if(monthsSinceStart % monthStep !== 0){
        const offset = monthStep - (monthsSinceStart % monthStep);
        candidate.setMonth(candidate.getMonth() + offset);
      }
    }
    
    if(cal.end_date && candidate > new Date(cal.end_date)) return null;
    return candidate;
  },
  
  _formatDate(d){
    if(!d) return null;
    const dt = (d instanceof Date) ? d : new Date(d);
    return dt.toISOString().split('T')[0];
  },
  
  getUpcomingPayments(daysAhead = 7){
    const now = new Date();
    const cutoff = new Date(now.getTime() + daysAhead * 86400000);
    return this.CACHE.payments
      .filter(p => p.status === 'pending')
      .filter(p => new Date(p.due_date) <= cutoff)
      .sort((a,b) => new Date(a.due_date) - new Date(b.due_date));
  },
  
  getOverduePayments(){
    const today = new Date(); today.setHours(0,0,0,0);
    return this.CACHE.payments
      .filter(p => p.status === 'pending')
      .filter(p => new Date(p.due_date) < today)
      .sort((a,b) => new Date(a.due_date) - new Date(b.due_date));
  },
  
  getCalendarFor(paymentId){
    const pay = this.CACHE.payments.find(p => p.id === paymentId);
    if(!pay) return null;
    return this.CACHE.calendar.find(c => c.id === pay.expense_calendar_id);
  },
  
  async saveCalendarEntry(entry){
    try{
      const data = {
        shop_id: SHOP_ID,
        name: entry.name,
        category: entry.category || 'other',
        default_amount: entry.default_amount || null,
        is_variable: !!entry.is_variable,
        frequency: entry.frequency,
        day_of_month: entry.day_of_month,
        start_date: entry.start_date || this._formatDate(new Date()),
        end_date: entry.end_date || null,
        notify_days_before: entry.notify_days_before ?? 5,
        notify_browser: entry.notify_browser !== false,
        notify_in_app: entry.notify_in_app !== false,
        auto_add_to_cashbook: entry.auto_add_to_cashbook !== false,
        cashbook_category: entry.cashbook_category || entry.name,
        send_to_accountant: entry.send_to_accountant !== false,
        notes: entry.notes || null,
        is_active: true
      };
      let result;
      if(entry.id){
        result = await sb.from('expense_calendar').update(data).eq('id', entry.id).select().single();
      } else {
        result = await sb.from('expense_calendar').insert(data).select().single();
      }
      if(result.error){
        console.error('[ExpenseCalendar] DB error:', result.error);
        // Πιο specific error message
        const msg = result.error.message || '';
        if(/relation.*does not exist|table.*does not exist/i.test(msg)){
          throw new Error('Ο πίνακας expense_calendar δεν υπάρχει. Τρέξε το SQL migration στο Supabase.');
        }
        if(/permission denied|RLS/i.test(msg)){
          throw new Error('Δεν έχεις permission. Έλεγξε ότι έτρεξε σωστά το migration με τα RLS policies.');
        }
        throw new Error(msg || 'Άγνωστο σφάλμα DB');
      }
      await this.load();
      return result.data;
    }catch(e){
      console.error('[ExpenseCalendar] save error:', e);
      throw e;
    }
  },
  
  async deleteCalendarEntry(id){
    try{
      const { error } = await sb.from('expense_calendar').update({ is_active: false }).eq('id', id);
      if(error) throw error;
      await this.load();
      return true;
    }catch(e){
      console.error('[ExpenseCalendar] delete error:', e);
      throw e;
    }
  },
  
  async confirmPayment(paymentId, opts){
    const pay = this.CACHE.payments.find(p => p.id === paymentId);
    if(!pay) throw new Error('Payment not found');
    const cal = this.CACHE.calendar.find(c => c.id === pay.expense_calendar_id);
    if(!cal) throw new Error('Calendar entry not found');
    
    const amount = opts?.amount ?? cal.default_amount ?? 0;
    const paidDate = opts?.paidDate || this._formatDate(new Date());
    const receiptUrl = opts?.receiptUrl || null;
    
    try{
      const { error: payErr } = await sb.from('expense_payments').update({
        status: 'paid',
        paid_date: paidDate,
        amount_paid: amount,
        receipt_url: receiptUrl,
        notes: opts?.notes || null
      }).eq('id', paymentId);
      if(payErr) throw payErr;
      
      let cashbookId = null;
      if(cal.auto_add_to_cashbook && amount > 0){
        try{
          const cashEntry = {
            shop_id: SHOP_ID,
            type: 'expense',
            amount: amount,
            category: cal.cashbook_category || cal.name,
            description: `${cal.name} (${this._formatDate(pay.due_date)})`,
            date: paidDate,
            payment_method: opts?.paymentMethod || 'bank',
            notes: opts?.notes || null
          };
          const { data: cashData, error: cashErr } = await sb.from('cash_movements').insert(cashEntry).select().single();
          if(!cashErr && cashData){
            cashbookId = cashData.id;
            await sb.from('expense_payments').update({ cashbook_entry_id: cashbookId }).eq('id', paymentId);
          }
        }catch(cashE){ 
          console.warn('[ExpenseCalendar] cashbook insert failed:', cashE);
          if(typeof toast === 'function') toast('Πληρωμή καταγράφηκε, αλλά δεν προστέθηκε στο Ταμείο','warning');
        }
      }
      
      await this.load();
      if(typeof loadCashbook === 'function') loadCashbook();
      return { success: true, cashbookId };
    }catch(e){
      console.error('[ExpenseCalendar] confirm error:', e);
      throw e;
    }
  },
  
  async skipPayment(paymentId, reason){
    try{
      const { error } = await sb.from('expense_payments').update({
        status: 'skipped',
        notes: reason || 'Παραλείφθηκε'
      }).eq('id', paymentId);
      if(error) throw error;
      await this.load();
      return true;
    }catch(e){
      console.error('[ExpenseCalendar] skip error:', e);
      throw e;
    }
  },
  
  async uploadReceipt(paymentId, file){
    if(!file) return null;
    const ext = (file.name || 'pdf').split('.').pop().toLowerCase();
    const safeName = `receipt_${paymentId}_${Date.now()}.${ext}`;
    const path = `${SHOP_ID}/${safeName}`;
    try{
      const { error } = await sb.storage.from(this.RECEIPT_BUCKET).upload(path, file, {
        upsert: true,
        contentType: file.type || (ext === 'pdf' ? 'application/pdf' : 'image/jpeg')
      });
      if(error) throw error;
      return path;
    }catch(e){
      console.error('[ExpenseCalendar] upload error:', e);
      throw e;
    }
  },
  
  async getReceiptUrl(path){
    if(!path) return null;
    try{
      const { data, error } = await sb.storage.from(this.RECEIPT_BUCKET).createSignedUrl(path, 3600);
      if(error) throw error;
      return data?.signedUrl || null;
    }catch(e){
      console.error('[ExpenseCalendar] signed URL:', e);
      return null;
    }
  }
};
window.EXPENSE_CALENDAR = EXPENSE_CALENDAR;

// --- expense-calendar render & UI sub-module ---
// 💀 DEAD STOCK RECOVERY — dedicated page με ZyroNex suggestions και combos
// ════════════════════════════════════════════════════════════════════════

// ════════════════════════════════════════════════════════════════════════
// 📅 EXPENSE CALENDAR — Render & UI
// ════════════════════════════════════════════════════════════════════════
var EXP_CAL_FILTER = 'upcoming'; // upcoming | overdue | paid | all
window.EXP_CAL_FILTER = EXP_CAL_FILTER;

async function renderExpenseCalendar(){
  // Loading state πρώτα
  document.getElementById('content').innerHTML = `
    <div class="page-head">
      <div>
        <h1 class="page-title">📅 Ημερολόγιο Εξόδων</h1>
        <p class="page-sub">Φόρτωση...</p>
      </div>
    </div>
  `;
  
  await EXPENSE_CALENDAR.load();
  _renderExpenseCalendarPage();
}
window.renderExpenseCalendar = renderExpenseCalendar;

function _renderExpenseCalendarPage(){
  const calendar = EXPENSE_CALENDAR.CACHE.calendar;
  const payments = EXPENSE_CALENDAR.CACHE.payments;
  const upcoming = EXPENSE_CALENDAR.getUpcomingPayments(30);
  const overdue = EXPENSE_CALENDAR.getOverduePayments();
  const paid = payments.filter(p => p.status === 'paid').slice(0, 50);
  
  // Stats
  const monthlyTotal = calendar
    .filter(c => c.frequency === 'monthly' && c.default_amount)
    .reduce((s,c) => s + parseFloat(c.default_amount || 0), 0);
  const upcomingCount = upcoming.length;
  const overdueCount = overdue.length;
  
  // Empty state - πρώτη φορά
  if(calendar.length === 0){
    document.getElementById('content').innerHTML = `
      <div class="page-head">
        <div>
          <h1 class="page-title">📅 Ημερολόγιο Εξόδων</h1>
          <p class="page-sub">Διαχείριση επαναλαμβανόμενων εξόδων με υπενθυμίσεις</p>
        </div>
      </div>
      
      <div class="card" style="text-align:center;padding:40px 20px">
        <div style="font-size:50px;margin-bottom:12px">📅</div>
        <div class="fw-800" style="font-size:18px;margin-bottom:6px">Ξεκίνα με τα συνηθισμένα έξοδα</div>
        <div class="text-sm muted" style="max-width:380px;margin:0 auto 20px">
          Πρόσθεσε ενοίκιο, ΕΦΚΑ, ΔΕΗ, λογιστή κλπ. Η εφαρμογή θα σε υπενθυμίζει 5 ημέρες πριν κάθε πληρωμή.
        </div>
        
        <div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap">
          <button class="btn btn-primary" onclick="_openAddExpensePresetsPicker()">
            <i data-lucide="zap" size="16"></i> Γρήγορη Προσθήκη Συνηθισμένων
          </button>
          <button class="btn btn-ghost" onclick="_openExpenseCalendarEditor()">
            <i data-lucide="plus" size="16"></i> Προσθήκη Έξτρα
          </button>
        </div>
      </div>
    `;
    if(typeof lucide !== 'undefined') lucide.createIcons();
    return;
  }
  
  const html = `
    <div class="page-head">
      <div>
        <h1 class="page-title">📅 Ημερολόγιο Εξόδων</h1>
        <p class="page-sub">${calendar.length} ενεργά έξοδα · ${upcomingCount} επερχόμενες πληρωμές</p>
      </div>
      <div class="flex gap-2" style="flex-wrap:wrap">
        <button class="btn btn-ghost" onclick="_openAddExpensePresetsPicker()" title="Προσθήκη preset">
          <i data-lucide="zap" size="16"></i> Presets
        </button>
        <button class="btn btn-primary" onclick="_openExpenseCalendarEditor()">
          <i data-lucide="plus" size="16"></i> Νέο Έξοδο
        </button>
      </div>
    </div>
    
    <!-- KPI Cards -->
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-bottom:14px">
      ${overdueCount > 0 ? `
      <div class="card" style="padding:14px;border-left:3px solid var(--danger);background:rgba(231,76,60,0.05)">
        <div class="text-xs muted">🚨 Καθυστερήσεις</div>
        <div class="kpi-value" style="font-size:22px;font-weight:800;color:var(--danger)">${overdueCount}</div>
        <div class="text-xs muted">πληρωμές</div>
      </div>
      ` : ''}
      <div class="card" style="padding:14px;border-left:3px solid #f39c12">
        <div class="text-xs muted">📅 Επερχόμενες (30d)</div>
        <div class="kpi-value" style="font-size:22px;font-weight:800;color:#f39c12">${upcomingCount}</div>
        <div class="text-xs muted">πληρωμές</div>
      </div>
      ${monthlyTotal > 0 ? `
      <div class="card" style="padding:14px;border-left:3px solid var(--accent)">
        <div class="text-xs muted">💰 Μηνιαία Σταθερά</div>
        <div class="kpi-value" style="font-size:22px;font-weight:800;color:var(--accent)">${eur(monthlyTotal)}</div>
        <div class="text-xs muted">εκτίμηση</div>
      </div>
      ` : ''}
    </div>
    
    <!-- Tabs -->
    <div class="card" style="padding:8px;margin-bottom:14px;display:flex;gap:6px;flex-wrap:wrap">
      <button class="tab ${EXP_CAL_FILTER==='upcoming'?'active':''}" onclick="EXP_CAL_FILTER='upcoming';_renderExpenseCalendarPage()">
        📅 Επερχόμενες <span class="muted" style="margin-left:4px;font-size:11px">${upcomingCount}</span>
      </button>
      ${overdueCount > 0 ? `
      <button class="tab ${EXP_CAL_FILTER==='overdue'?'active':''}" onclick="EXP_CAL_FILTER='overdue';_renderExpenseCalendarPage()" style="color:var(--danger)">
        🚨 Καθυστερήσεις <span class="muted" style="margin-left:4px;font-size:11px">${overdueCount}</span>
      </button>
      ` : ''}
      <button class="tab ${EXP_CAL_FILTER==='paid'?'active':''}" onclick="EXP_CAL_FILTER='paid';_renderExpenseCalendarPage()">
        ✅ Ιστορικό
      </button>
      <button class="tab ${EXP_CAL_FILTER==='all'?'active':''}" onclick="EXP_CAL_FILTER='all';_renderExpenseCalendarPage()">
        ⚙️ Ρυθμίσεις
      </button>
    </div>
    
    <!-- Content -->
    <div id="expCalContent">
      ${EXP_CAL_FILTER === 'upcoming' ? _renderUpcomingPayments(upcoming) : ''}
      ${EXP_CAL_FILTER === 'overdue' ? _renderOverduePayments(overdue) : ''}
      ${EXP_CAL_FILTER === 'paid' ? _renderPaidHistory(paid) : ''}
      ${EXP_CAL_FILTER === 'all' ? _renderCalendarSettings(calendar) : ''}
    </div>
  `;
  
  document.getElementById('content').innerHTML = html;
  if(typeof lucide !== 'undefined') lucide.createIcons();
}

function _renderUpcomingPayments(upcoming){
  if(upcoming.length === 0){
    return `<div class="card" style="text-align:center;padding:40px 20px"><div class="muted">Δεν υπάρχουν επερχόμενες πληρωμές</div></div>`;
  }
  
  // Group by month
  const groups = {};
  for(const p of upcoming){
    const due = new Date(p.due_date);
    const monthKey = `${due.getFullYear()}-${String(due.getMonth()+1).padStart(2,'0')}`;
    if(!groups[monthKey]) groups[monthKey] = { label: due.toLocaleDateString('el-GR', { month: 'long', year: 'numeric' }), items: [] };
    groups[monthKey].items.push(p);
  }
  
  const monthsHtml = Object.entries(groups).map(([key, g]) => {
    const total = g.items.reduce((s,p) => {
      const cal = EXPENSE_CALENDAR.getCalendarFor(p.id);
      return s + parseFloat(cal?.default_amount || 0);
    }, 0);
    return `
    <div class="card" style="padding:14px;margin-bottom:10px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <div class="fw-800" style="font-size:14px;text-transform:capitalize">${g.label}</div>
        ${total > 0 ? `<div class="text-xs muted">Σύνολο εκτίμησης: <b style="color:var(--accent)">${eur(total)}</b></div>` : ''}
      </div>
      <div style="display:flex;flex-direction:column;gap:8px">
        ${g.items.map(p => _renderPaymentRow(p)).join('')}
      </div>
    </div>`;
  }).join('');
  
  return monthsHtml;
}

function _renderPaymentRow(payment){
  const cal = EXPENSE_CALENDAR.getCalendarFor(payment.id);
  if(!cal) return '';
  const due = new Date(payment.due_date);
  const today = new Date(); today.setHours(0,0,0,0);
  const daysUntil = Math.floor((due - today) / 86400000);
  
  let urgencyColor = 'var(--border)';
  let urgencyLabel = '';
  if(daysUntil < 0){
    urgencyColor = 'var(--danger)';
    urgencyLabel = `<span style="color:var(--danger);font-size:11px;font-weight:700">⚠️ ${Math.abs(daysUntil)}d καθυστέρηση</span>`;
  } else if(daysUntil === 0){
    urgencyColor = 'var(--danger)';
    urgencyLabel = `<span style="color:var(--danger);font-size:11px;font-weight:700">📅 Σήμερα!</span>`;
  } else if(daysUntil <= 5){
    urgencyColor = '#f39c12';
    urgencyLabel = `<span style="color:#f39c12;font-size:11px;font-weight:700">⏰ Σε ${daysUntil}d</span>`;
  } else {
    urgencyLabel = `<span class="muted" style="font-size:11px">σε ${daysUntil} ημέρες</span>`;
  }
  
  const catLabel = EXPENSE_CALENDAR.CATEGORY_LABELS[cal.category] || EXPENSE_CALENDAR.CATEGORY_LABELS.other;
  const amountDisplay = cal.is_variable 
    ? `<span class="muted" style="font-size:12px">(μεταβλητό)</span>` 
    : (cal.default_amount ? `<b>${eur(cal.default_amount)}</b>` : `<span class="muted">—</span>`);
  
  return `
  <div style="padding:12px;background:var(--bg-2);border-radius:8px;border-left:3px solid ${urgencyColor}">
    <div style="display:flex;justify-content:space-between;align-items:start;gap:10px;margin-bottom:8px;flex-wrap:wrap">
      <div style="flex:1;min-width:0">
        <div class="fw-700" style="font-size:14px">${catLabel.icon} ${escapeHtml(cal.name)}</div>
        <div class="text-xs muted" style="margin-top:2px">${due.toLocaleDateString('el-GR', { weekday: 'short', day: 'numeric', month: 'short' })} · ${amountDisplay}</div>
      </div>
      ${urgencyLabel}
    </div>
    <div style="display:flex;gap:6px;flex-wrap:wrap">
      <button class="btn btn-primary" style="padding:6px 12px;font-size:12px;flex:1;min-width:120px" onclick="_openConfirmPaymentModal(${payment.id})">
        <i data-lucide="check-circle" size="14"></i> Πληρώθηκε
      </button>
      <button class="btn btn-ghost" style="padding:6px 12px;font-size:12px" onclick="_skipPaymentConfirm(${payment.id})" title="Παράλειψη">
        <i data-lucide="skip-forward" size="14"></i>
      </button>
    </div>
  </div>`;
}

function _renderOverduePayments(overdue){
  if(overdue.length === 0){
    return `<div class="card" style="text-align:center;padding:40px 20px"><div class="muted">🎉 Δεν υπάρχουν καθυστερήσεις!</div></div>`;
  }
  return `<div class="card" style="padding:14px">
    <div style="display:flex;flex-direction:column;gap:8px">
      ${overdue.map(p => _renderPaymentRow(p)).join('')}
    </div>
  </div>`;
}

function _renderPaidHistory(paid){
  if(paid.length === 0){
    return `<div class="card" style="text-align:center;padding:40px 20px"><div class="muted">Δεν υπάρχει ιστορικό πληρωμών</div></div>`;
  }
  return `<div class="card" style="padding:14px">
    <div style="display:flex;flex-direction:column;gap:6px">
      ${paid.map(p => {
        const cal = EXPENSE_CALENDAR.getCalendarFor(p.id);
        if(!cal) return '';
        const catLabel = EXPENSE_CALENDAR.CATEGORY_LABELS[cal.category] || EXPENSE_CALENDAR.CATEGORY_LABELS.other;
        const paidDate = new Date(p.paid_date || p.due_date);
        return `
        <div style="padding:10px;background:var(--bg-2);border-radius:8px;display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap">
          <div style="flex:1;min-width:0">
            <div class="fw-700" style="font-size:13px">${catLabel.icon} ${escapeHtml(cal.name)}</div>
            <div class="text-xs muted">${paidDate.toLocaleDateString('el-GR')} · <b>${eur(p.amount_paid || 0)}</b></div>
          </div>
          ${p.receipt_url ? `<button class="icon-btn" onclick="_viewExpenseReceipt('${p.receipt_url}')" title="Απόδειξη"><i data-lucide="paperclip" size="14"></i></button>` : ''}
        </div>`;
      }).join('')}
    </div>
  </div>`;
}

function _renderCalendarSettings(calendar){
  if(calendar.length === 0){
    return `<div class="card" style="text-align:center;padding:40px 20px"><div class="muted">Δεν υπάρχουν έξοδα στο ημερολόγιο</div></div>`;
  }
  return `<div class="card" style="padding:14px">
    <div style="display:flex;flex-direction:column;gap:8px">
      ${calendar.map(c => {
        const catLabel = EXPENSE_CALENDAR.CATEGORY_LABELS[c.category] || EXPENSE_CALENDAR.CATEGORY_LABELS.other;
        const freqLabel = EXPENSE_CALENDAR.FREQUENCY_LABELS[c.frequency] || c.frequency;
        return `
        <div style="padding:12px;background:var(--bg-2);border-radius:8px">
          <div style="display:flex;justify-content:space-between;align-items:start;gap:10px;margin-bottom:6px;flex-wrap:wrap">
            <div style="flex:1;min-width:0">
              <div class="fw-700" style="font-size:14px">${catLabel.icon} ${escapeHtml(c.name)}</div>
              <div class="text-xs muted" style="margin-top:3px">
                ${freqLabel} · ημέρα ${c.day_of_month || '—'} · ${c.is_variable ? 'μεταβλητό' : (c.default_amount ? eur(c.default_amount) : '—')}
                · ειδοποίηση ${c.notify_days_before || 5}d πριν
              </div>
            </div>
            <div style="display:flex;gap:4px">
              <button class="icon-btn" onclick="_openExpenseCalendarEditor(${c.id})" title="Επεξεργασία">
                <i data-lucide="edit" size="14"></i>
              </button>
              <button class="icon-btn" style="color:var(--danger)" onclick="_deleteExpenseCalendarConfirm(${c.id})" title="Διαγραφή">
                <i data-lucide="trash-2" size="14"></i>
              </button>
            </div>
          </div>
        </div>`;
      }).join('')}
    </div>
  </div>`;
}

window._renderExpenseCalendarPage = _renderExpenseCalendarPage;

// ── Editor: προσθήκη/επεξεργασία calendar entry ─────────────────────────
function _openExpenseCalendarEditor(id){
  const entry = id ? EXPENSE_CALENDAR.CACHE.calendar.find(c => c.id === id) : null;
  const isEdit = !!entry;
  const today = new Date().toISOString().split('T')[0];
  
  const html = `<div class="modal-head">
    <h3 class="fw-800 text-xl">${isEdit ? '✏️ Επεξεργασία' : '➕ Νέο'} Έξοδο</h3>
    <button class="icon-btn" onclick="closeModal()"><i data-lucide="x" size="16"></i></button>
  </div>
  <div class="modal-body">
    <form id="expCalForm" onsubmit="event.preventDefault();_submitExpenseCalendarForm(${id || 'null'})" style="display:flex;flex-direction:column;gap:12px">
      
      <!-- Name -->
      <div>
        <label class="form-label">Όνομα <span style="color:var(--danger)">*</span></label>
        <input class="form-input" name="name" required value="${escapeHtml(entry?.name || '')}" placeholder="πχ Ενοίκιο, ΕΦΚΑ, ΔΕΗ">
      </div>
      
      <!-- Category -->
      <div>
        <label class="form-label">Κατηγορία</label>
        <select class="form-input" name="category">
          ${Object.entries(EXPENSE_CALENDAR.CATEGORY_LABELS).map(([key, lbl]) => 
            `<option value="${key}" ${(entry?.category||'other')===key?'selected':''}>${lbl.icon} ${lbl.el}</option>`
          ).join('')}
        </select>
      </div>
      
      <!-- Frequency + Day -->
      <div class="form-grid">
        <div>
          <label class="form-label">Συχνότητα <span style="color:var(--danger)">*</span></label>
          <select class="form-input" name="frequency" required onchange="_toggleOneOffDate(this.value)">
            ${Object.entries(EXPENSE_CALENDAR.FREQUENCY_LABELS).map(([key, lbl]) => 
              `<option value="${key}" ${(entry?.frequency||'monthly')===key?'selected':''}>${lbl}</option>`
            ).join('')}
          </select>
        </div>
        <div id="dayOfMonthWrap" style="${entry?.frequency==='oneoff'?'display:none':''}">
          <label class="form-label">Ημέρα του μήνα <span style="color:var(--danger)">*</span></label>
          <input class="form-input" name="day_of_month" type="number" min="1" max="28" value="${entry?.day_of_month || 5}">
        </div>
        <div id="oneOffDateWrap" style="${entry?.frequency==='oneoff'?'':'display:none'}">
          <label class="form-label">Ημερομηνία</label>
          <input class="form-input" name="oneoff_date" type="date" value="${entry?.start_date || today}">
        </div>
      </div>
      
      <!-- Variable amount checkbox -->
      <label style="display:flex;align-items:center;gap:8px;padding:10px;background:var(--bg-2);border-radius:8px;cursor:pointer">
        <input type="checkbox" name="is_variable" ${entry?.is_variable?'checked':''} onchange="_toggleVariableAmount(this)" style="width:18px;height:18px;accent-color:var(--accent)">
        <span style="flex:1">
          <div class="fw-700" style="font-size:13px">Μεταβλητό ποσό</div>
          <div class="text-xs muted">Η εφαρμογή θα ζητάει το ποσό κάθε φορά (πχ ΔΕΗ, ΕΥΔΑΠ)</div>
        </span>
      </label>
      
      <!-- Default amount (μόνο όταν δεν είναι variable) -->
      <div id="defaultAmountWrap" style="${entry?.is_variable?'display:none':''}">
        <label class="form-label">Σταθερό ποσό (€)</label>
        <input class="form-input" name="default_amount" type="number" step="0.01" min="0" value="${entry?.default_amount || ''}" placeholder="πχ 450.00">
      </div>
      
      <!-- Notify days -->
      <div>
        <label class="form-label">Ειδοποίηση πόσες ημέρες πριν;</label>
        <input class="form-input" name="notify_days_before" type="number" min="0" max="60" value="${entry?.notify_days_before ?? 5}">
      </div>
      
      <!-- Cashbook category -->
      <div>
        <label class="form-label">Κατηγορία Ταμείου</label>
        <input class="form-input" name="cashbook_category" value="${escapeHtml(entry?.cashbook_category || '')}" placeholder="πχ Ενοίκιο (ονομασία στο Ταμείο)">
        <div class="text-xs muted" style="margin-top:4px">Όταν επιβεβαιώνεις πληρωμή, μπαίνει αυτόματα στο Ταμείο σαν έξοδο με αυτή την κατηγορία.</div>
      </div>
      
      <!-- Toggles -->
      <div style="display:flex;flex-direction:column;gap:8px">
        <label style="display:flex;align-items:center;gap:8px">
          <input type="checkbox" name="auto_add_to_cashbook" ${entry?.auto_add_to_cashbook!==false?'checked':''} style="width:16px;height:16px;accent-color:var(--accent)">
          <span style="font-size:13px">Αυτόματη καταχώρηση στο Ταμείο όταν πληρωθεί</span>
        </label>
        <label style="display:flex;align-items:center;gap:8px">
          <input type="checkbox" name="send_to_accountant" ${entry?.send_to_accountant!==false?'checked':''} style="width:16px;height:16px;accent-color:var(--accent)">
          <span style="font-size:13px">Συμπερίληψη στο μηνιαίο email προς λογιστή (μαζί με αποδείξεις)</span>
        </label>
        <label style="display:flex;align-items:center;gap:8px">
          <input type="checkbox" name="notify_browser" ${entry?.notify_browser!==false?'checked':''} style="width:16px;height:16px;accent-color:var(--accent)">
          <span style="font-size:13px">Browser push notification (αν επιτρέψεις)</span>
        </label>
      </div>
      
      <!-- Notes -->
      <div>
        <label class="form-label">Σημειώσεις</label>
        <textarea class="form-input" name="notes" rows="2" placeholder="Όροι, IBAN, παρατηρήσεις...">${escapeHtml(entry?.notes || '')}</textarea>
      </div>
      
      <!-- Reference document (συμβόλαιο, ενημερωτικό κλπ) -->
      <div>
        <label class="form-label">📎 Έγγραφο αναφοράς (προαιρετικό)</label>
        ${entry?.reference_doc_url ? `
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;padding:8px;background:var(--bg-2);border-radius:6px">
          <i data-lucide="file" size="14"></i>
          <span class="text-xs" style="flex:1">Υπάρχει αρχείο</span>
          <button type="button" class="btn btn-ghost" style="padding:4px 8px;font-size:11px" onclick="_viewExpenseReceipt('${entry.reference_doc_url.replace(/'/g,"\\'")}')">
            👁️ Δες
          </button>
        </div>
        ` : ''}
        <input type="file" name="reference_file" accept="application/pdf,image/*" class="form-input" style="padding:10px">
        <div class="text-xs muted" style="margin-top:4px">πχ συμβόλαιο ενοικίου, εκκαθαριστικό ΕΦΚΑ. Διαφορετικό από τις αποδείξεις πληρωμών.</div>
      </div>
      
      <!-- Submit -->
      <div style="display:flex;gap:8px;margin-top:8px">
        <button type="submit" class="btn btn-primary" style="flex:1">
          <i data-lucide="save" size="14"></i> ${isEdit ? 'Αποθήκευση' : 'Δημιουργία'}
        </button>
        <button type="button" class="btn btn-ghost" onclick="closeModal()">Ακύρωση</button>
      </div>
    </form>
  </div>`;
  
  openModal(html);
}
window._openExpenseCalendarEditor = _openExpenseCalendarEditor;

function _toggleVariableAmount(cb){
  const wrap = document.getElementById('defaultAmountWrap');
  if(wrap) wrap.style.display = cb.checked ? 'none' : '';
}
window._toggleVariableAmount = _toggleVariableAmount;

function _toggleOneOffDate(freq){
  const dayWrap = document.getElementById('dayOfMonthWrap');
  const dateWrap = document.getElementById('oneOffDateWrap');
  if(freq === 'oneoff'){
    if(dayWrap) dayWrap.style.display = 'none';
    if(dateWrap) dateWrap.style.display = '';
  } else {
    if(dayWrap) dayWrap.style.display = '';
    if(dateWrap) dateWrap.style.display = 'none';
  }
}
window._toggleOneOffDate = _toggleOneOffDate;

async function _submitExpenseCalendarForm(id){
  const form = document.getElementById('expCalForm');
  if(!form) return;
  const fd = new FormData(form);
  
  const frequency = fd.get('frequency');
  const oneOffDate = fd.get('oneoff_date');
  const dayOfMonth = parseInt(fd.get('day_of_month')) || 5;
  const referenceFile = fd.get('reference_file');
  
  const entry = {
    id: id || undefined,
    name: fd.get('name'),
    category: fd.get('category'),
    frequency,
    day_of_month: frequency === 'oneoff' ? (oneOffDate ? new Date(oneOffDate).getDate() : 1) : dayOfMonth,
    start_date: frequency === 'oneoff' ? oneOffDate : null,
    is_variable: !!fd.get('is_variable'),
    default_amount: fd.get('is_variable') ? null : (parseFloat(fd.get('default_amount')) || null),
    notify_days_before: parseInt(fd.get('notify_days_before')) || 5,
    cashbook_category: fd.get('cashbook_category') || fd.get('name'),
    auto_add_to_cashbook: !!fd.get('auto_add_to_cashbook'),
    send_to_accountant: !!fd.get('send_to_accountant'),
    notify_browser: !!fd.get('notify_browser'),
    notes: fd.get('notes') || null
  };
  
  if(!entry.name || !entry.frequency){
    toast('Συμπλήρωσε όνομα και συχνότητα', 'warning');
    return;
  }
  
  try{
    // 1. Save entry first
    const saved = await EXPENSE_CALENDAR.saveCalendarEntry(entry);
    
    // 2. Upload reference doc (αν υπάρχει)
    if(referenceFile && referenceFile.size > 0 && saved?.id){
      try{
        let fileToUpload = referenceFile;
        if(referenceFile.type?.startsWith('image/') && referenceFile.size > 5*1024*1024 && typeof _compressImageIfNeeded === 'function'){
          fileToUpload = await _compressImageIfNeeded(referenceFile);
        }
        const ext = (fileToUpload.name || 'pdf').split('.').pop().toLowerCase();
        const path = `${SHOP_ID}/ref_${saved.id}_${Date.now()}.${ext}`;
        const { error: upErr } = await sb.storage.from(EXPENSE_CALENDAR.RECEIPT_BUCKET).upload(path, fileToUpload, {
          upsert: true,
          contentType: fileToUpload.type || (ext === 'pdf' ? 'application/pdf' : 'image/jpeg')
        });
        if(upErr) throw upErr;
        // Update entry με reference_doc_url
        await sb.from('expense_calendar').update({ reference_doc_url: path }).eq('id', saved.id);
      }catch(uploadErr){
        console.error('[Reference upload]', uploadErr);
        toast('Έξοδο αποθηκεύτηκε αλλά το έγγραφο αναφοράς απέτυχε', 'warning');
      }
    }
    
    toast(`✅ ${id ? 'Ενημερώθηκε' : 'Προστέθηκε'}: ${entry.name}`, 'success');
    closeModal();
    await EXPENSE_CALENDAR.load();
    _renderExpenseCalendarPage();
    _updateExpCalBadge();
  }catch(e){
    console.error('[ExpCal save]', e);
    alert(`⚠️ Αποθήκευση απέτυχε:\n\n${e.message || e}\n\nΠιθανή αιτία: δεν έχει τρέξει το migration_expense_calendar.sql`);
  }
}
window._submitExpenseCalendarForm = _submitExpenseCalendarForm;

// ── Confirm Payment Modal ─────────────────────────────────────────────────
