// ── Presets Picker ───────────────────────────────────────────────────────
function _openAddExpensePresetsPicker(){
  const existingNames = new Set(EXPENSE_CALENDAR.CACHE.calendar.map(c => c.name.toLowerCase()));
  const available = EXPENSE_CALENDAR.DEFAULT_PRESETS.filter(p => !existingNames.has(p.name.toLowerCase()));
  
  if(available.length === 0){
    toast('Έχεις ήδη όλα τα presets — πρόσθεσε custom έξοδο','info');
    return;
  }
  
  openModal(`<div class="modal-head">
    <h3 class="fw-800 text-xl">⚡ Γρήγορη Προσθήκη Presets</h3>
    <button class="icon-btn" onclick="closeModal()"><i data-lucide="x" size="16"></i></button>
  </div>
  <div class="modal-body">
    <div class="text-sm muted" style="margin-bottom:14px">Επίλεξε ποια θες να προσθέσεις. Μπορείς να τα τροποποιήσεις μετά.</div>
    <div style="display:flex;flex-direction:column;gap:8px">
      ${available.map((p, idx) => {
        const freqLabel = EXPENSE_CALENDAR.FREQUENCY_LABELS[p.frequency];
        return `
        <label style="display:flex;align-items:center;gap:10px;padding:12px;background:var(--bg-2);border:1px solid var(--border);border-radius:10px;cursor:pointer">
          <input type="checkbox" class="preset-cb" data-idx="${idx}" style="width:18px;height:18px;accent-color:var(--accent);flex-shrink:0">
          <div style="flex:1;min-width:0">
            <div class="fw-700" style="font-size:14px">${p.icon} ${escapeHtml(p.name)}</div>
            <div class="text-xs muted" style="margin-top:2px">${freqLabel} · ημέρα ${p.day_of_month} ${p.is_variable ? '· μεταβλητό' : ''}</div>
          </div>
        </label>`;
      }).join('')}
    </div>
    <div style="display:flex;gap:8px;margin-top:16px">
      <button class="btn btn-primary" style="flex:1" onclick="_confirmAddPresets()">
        <i data-lucide="plus" size="14"></i> Προσθήκη Επιλεγμένων
      </button>
      <button class="btn btn-ghost" onclick="closeModal()">Ακύρωση</button>
    </div>
  </div>`);
  
  // Pre-check όλα
  setTimeout(() => {
    document.querySelectorAll('.preset-cb').forEach(cb => cb.checked = true);
  }, 50);
}
window._openAddExpensePresetsPicker = _openAddExpensePresetsPicker;

async function _confirmAddPresets(){
  const checked = Array.from(document.querySelectorAll('.preset-cb:checked')).map(cb => parseInt(cb.dataset.idx));
  if(checked.length === 0){ toast('Επίλεξε τουλάχιστον ένα','warning'); return; }
  
  // Reload cache για να αποφύγουμε stale state (race condition αν πάτησε γρήγορα)
  await EXPENSE_CALENDAR.load();
  const existingNames = new Set(EXPENSE_CALENDAR.CACHE.calendar.map(c => c.name.toLowerCase()));
  const available = EXPENSE_CALENDAR.DEFAULT_PRESETS.filter(p => !existingNames.has(p.name.toLowerCase()));
  const selected = checked.map(i => available[i]).filter(Boolean);
  
  if(selected.length === 0){
    toast('Όλα τα επιλεγμένα υπάρχουν ήδη','info');
    closeModal();
    return;
  }
  
  toast('Προσθήκη...','info',1500);
  let ok = 0, fail = 0;
  const errors = [];
  
  for(const preset of selected){
    try{
      const result = await EXPENSE_CALENDAR.saveCalendarEntry({
        name: preset.name,
        category: preset.category,
        frequency: preset.frequency,
        day_of_month: preset.day_of_month,
        default_amount: preset.default_amount,
        is_variable: preset.is_variable,
        cashbook_category: preset.cashbook_category,
        notify_days_before: 5,
        notify_browser: true,
        notify_in_app: true,
        auto_add_to_cashbook: true,
        send_to_accountant: true
      });
      if(result && result.id) ok++;
      else { fail++; errors.push(`${preset.name}: άγνωστο σφάλμα`); }
    }catch(e){ 
      console.error(`[Preset Add] ${preset.name} failed:`, e);
      fail++; 
      errors.push(`${preset.name}: ${e.message || 'σφάλμα'}`);
    }
  }
  
  closeModal();
  
  if(fail > 0){
    // Visible alert με τι απέτυχε
    alert(`⚠️ Προστέθηκαν ${ok} από ${selected.length}.\n\nΑποτυχίες:\n${errors.join('\n')}\n\nΠιθανή αιτία: δεν έχει τρέξει το migration_expense_calendar.sql στο Supabase.`);
  } else {
    toast(`✅ Προστέθηκαν ${ok} έξοδα`, 'success');
  }
  
  await EXPENSE_CALENDAR.load();
  _renderExpenseCalendarPage();
  _updateExpCalBadge();
}
window._confirmAddPresets = _confirmAddPresets;

// ── Badge updater (στο sidebar nav item) ──────────────────────────────
function _updateExpCalBadge(){
  const badge = document.getElementById('expCalBadge');
  if(!badge) return;
  const upcoming = EXPENSE_CALENDAR.getUpcomingPayments(7).length;
  const overdue = EXPENSE_CALENDAR.getOverduePayments().length;
  const total = upcoming + overdue;
  if(total > 0){
    badge.textContent = total;
    badge.style.display = '';
    if(overdue > 0) badge.style.background = 'var(--danger)';
    else badge.style.background = '#f39c12';
  } else {
    badge.style.display = 'none';
  }
  if(typeof updateNotifDot === 'function') updateNotifDot();
}
window._updateExpCalBadge = _updateExpCalBadge;


// ════════════════════════════════════════════════════════════
//  PLUGIN MARKET — βιτρίνα προσθέτων (κάρτες + install/ενεργό)
// ════════════════════════════════════════════════════════════

// --- plugin-market render & actions sub-module ---
function renderPluginMarket(){
  var content = document.getElementById('content');
  if (!content) return;
  var isOwner = false;
  try { isOwner = _isOwnerBypass(); } catch(_) {}

  var cards = (ZYRONEX_PLUGINS || []).map(function(pl){
    var active = false;
    try { active = isPluginActive(pl.id); } catch(_) {}
    var installedManually = getInstalledPlugins().indexOf(pl.id) !== -1;

    var statusBadge;
    if (active) {
      var _pst = 'active', _pdl = null;
      try { _pst = getPluginState(pl.id); _pdl = getPluginDaysLeft(pl.id); } catch(_) {}
      if (_pst === 'warning' || _pst === 'urgent') {
        var _c = _pst === 'urgent' ? '#f39c12' : '#eab308';
        statusBadge = '<span style="background:' + _c + '22;color:' + _c + ';padding:3px 10px;border-radius:20px;font-size:11px;font-weight:700">⏳ Λήγει σε ' + _pdl + (_pdl === 1 ? ' μέρα' : ' μέρες') + '</span>';
      } else if (_pst === 'past_due' || _pst === 'readonly') {
        statusBadge = '<span style="background:rgba(239,68,68,0.16);color:#ef4444;padding:3px 10px;border-radius:20px;font-size:11px;font-weight:700">⚠️ Ληγμένη — ανανέωσε</span>';
      } else {
        statusBadge = '<span style="background:rgba(16,185,129,0.16);color:#10b981;padding:3px 10px;border-radius:20px;font-size:11px;font-weight:700">✓ Εγκατεστημένο</span>';
      }
    } else {
      statusBadge = '<span style="background:rgba(148,163,184,0.16);color:var(--text-2);padding:3px 10px;border-radius:20px;font-size:11px;font-weight:700">Διαθέσιμο</span>';
    }

    // App-Store λογική: ενεργό (owner ή αγορασμένο) → κουμπί "Άνοιγμα" στο μενού
    var actionBtn;
    if (active) {
      actionBtn = '<div style="display:flex;flex-direction:column;gap:6px">'
        + '<button class="btn btn-primary" style="width:100%;min-height:44px;font-size:13px" onclick="_pluginOpen(\'' + pl.id + '\')"><i data-lucide="external-link" size="14"></i> Άνοιγμα</button>'
        + (isOwner ? '<div style="font-size:10px;color:var(--text-2);text-align:center">👑 Ενεργό ως ιδιοκτήτης (χωρίς χρέωση)</div>' : (installedManually ? '<button class="btn btn-ghost" style="width:100%;min-height:40px;font-size:12px" onclick="_pluginUninstall(\'' + pl.id + '\')"><i data-lucide="trash-2" size="13"></i> Κατάργηση</button>' : ''))
        + '</div>';
    } else {
      var pr = pl.pricing || {};
      var mo = pr.monthly ? pr.monthly.toFixed(2).replace('.',',') : null;
      var ot = pr.oneTime ? String(pr.oneTime).replace('.',',') : null;
      actionBtn = '<div style="display:flex;flex-direction:column;gap:6px">'
        + (mo ? '<button class="btn btn-primary" style="width:100%;min-height:44px;font-size:13px" onclick="_pluginBuy(\'' + pl.id + '\',\'monthly\')"><i data-lucide="repeat" size="14"></i> Συνδρομή · ' + mo + '€/μήνα</button>' : '')
        + (ot ? '<button class="btn btn-ghost" style="width:100%;min-height:44px;font-size:13px" onclick="_pluginBuy(\'' + pl.id + '\',\'oneTime\')"><i data-lucide="badge-check" size="14"></i> Εφάπαξ αγορά · ' + ot + '€</button>' : '')
        + '</div>';
    }

    var stepsHtml = (pl.steps || []).map(function(s, i){
      return '<div style="display:flex;gap:8px;margin-bottom:4px;font-size:12px;color:var(--text-1)"><span style="color:var(--accent);font-weight:700">' + (i+1) + '.</span><span>' + escapeHtml(s) + '</span></div>';
    }).join('');

    return '<div style="background:var(--bg-1);border:1px solid var(--border);border-radius:16px;padding:18px;display:flex;flex-direction:column;gap:10px;height:100%">'
      + '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px">'
      +   '<div style="display:flex;align-items:center;gap:10px"><div style="font-size:30px;line-height:1">' + pl.icon + '</div>'
      +     '<div><div style="font-weight:800;font-size:15px">' + escapeHtml(pl.name) + '</div>'
      +       '<div style="font-size:11px;color:var(--text-2)">' + escapeHtml(pl.category) + '</div></div></div>'
      +   statusBadge
      + '</div>'
      + '<div style="font-size:13px;color:var(--text-1)">' + escapeHtml(pl.tagline) + '</div>'
      + '<div style="font-size:12px;color:var(--text-2);line-height:1.5">' + escapeHtml(pl.about) + '</div>'
      + '<div style="background:var(--bg-2);border-radius:10px;padding:10px 12px">'
      +   '<div style="font-size:11px;font-weight:700;color:var(--text-1);margin-bottom:6px">Πώς δουλεύει</div>' + stepsHtml
      + '</div>'
      + '<div style="font-size:12px;color:#10b981;background:rgba(16,185,129,0.08);border-radius:8px;padding:8px 10px"><b>Αποτέλεσμα:</b> ' + escapeHtml(pl.result) + '</div>'
      + '<div style="font-size:11px;color:var(--text-2)">📍 ' + escapeHtml(pl.location) + '</div>'
      + '<div style="margin-top:auto;padding-top:10px">' + actionBtn + '</div>'
      + '</div>';
  }).join('');

  content.innerHTML =
    '<div class="page-head"><div>'
    + '<div class="page-title">🧩 ZyroNex Plugin Market</div>'
    + '<div class="page-sub">Πρόσθετα που επεκτείνουν το ZyroNex — εγκατάσταση με ένα κλικ</div>'
    + '</div></div>'
    + (isOwner ? '<div style="background:rgba(99,102,241,0.1);border:1px solid rgba(99,102,241,0.25);border-radius:10px;padding:10px 14px;margin-bottom:14px;font-size:12px;color:#818cf8">👑 Ως ιδιοκτήτης, όλα τα πρόσθετα είναι ήδη ενεργά για σένα.</div>' : '')
    + '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:16px;align-items:stretch">' + cards + '</div>';

  try { lucide.createIcons(); } catch(_) {}
}

function _pluginInstall(id){
  try {
    setPluginInstalled(id, true);
    var pl = (ZYRONEX_PLUGINS || []).find(function(p){ return p.id === id; });
    if (typeof toast === 'function') toast('✓ Εγκαταστάθηκε: ' + (pl ? pl.name : id), 'success');
    if (typeof renderPluginMarket === 'function') renderPluginMarket();
  } catch(_) {}
}
function _pluginBuy(id, mode){
  // mode: 'monthly' (συνδρομή) ή 'oneTime' (εφάπαξ)
  var pl = (ZYRONEX_PLUGINS || []).find(function(p){ return p.id === id; });
  if(!pl) return;
  var pr = pl.pricing || {};
  var label = mode==='oneTime'
    ? ('εφάπαξ αγορά · ' + String(pr.oneTime).replace('.',',') + '€')
    : ('μηνιαία συνδρομή · ' + (pr.monthly||0).toFixed(2).replace('.',',') + '€/μήνα');
  // Confirmation modal (standalone, mobile-safe)
  var ov = document.createElement('div');
  ov.style.cssText = 'position:fixed;inset:0;z-index:9000;background:rgba(0,0,0,.8);display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(6px)';
  ov.onclick = function(e){ if(e.target===ov) ov.remove(); };
  ov.innerHTML = '<div style="background:var(--bg-1);border:1px solid var(--border);border-radius:16px;padding:22px;max-width:380px;width:100%">'
    + '<div style="font-size:30px;margin-bottom:8px">' + pl.icon + '</div>'
    + '<div style="font-weight:800;font-size:17px;margin-bottom:4px">' + escapeHtml(pl.name) + '</div>'
    + '<div style="font-size:13px;color:var(--text-2);margin-bottom:16px">Επιβεβαίωση: ' + label + '</div>'
    + '<div style="font-size:12px;color:var(--text-2);background:var(--bg-2);border-radius:10px;padding:10px 12px;margin-bottom:16px">'
    + (mode==='oneTime' ? 'Πληρώνεις μία φορά και το πρόσθετο μένει ενεργό για πάντα.' : 'Χρεώνεσαι κάθε μήνα. Μπορείς να ακυρώσεις οποτεδήποτε.') + '</div>'
    + '<button id="_pbConfirm" class="btn btn-primary" style="width:100%;min-height:44px;margin-bottom:8px">Συνέχεια στην πληρωμή</button>'
    + '<button id="_pbCancel" class="btn btn-ghost" style="width:100%;min-height:44px">Άκυρο</button>'
    + '</div>';
  document.body.appendChild(ov);
  ov.querySelector('#_pbCancel').onclick = function(){ ov.remove(); };
  ov.querySelector('#_pbConfirm').onclick = async function(){
    var btn = ov.querySelector('#_pbConfirm');
    btn.disabled = true; btn.textContent = 'Σύνδεση με ασφαλή πληρωμή…';
    try {
      var resp = await fetch(SUPABASE_URL + '/functions/v1/plugin-checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY },
        body: JSON.stringify({ plugin_id: id, mode: mode, shop_id: SHOP_ID })
      });
      var data = await resp.json();
      if (data && data.checkout_url) {
        // Redirect to Stripe Checkout. On return, ?plugin_purchase=success refreshes state.
        window.location.href = data.checkout_url;
        return;
      }
      throw new Error((data && data.error) || 'Άγνωστο σφάλμα πληρωμής');
    } catch(e) {
      ov.remove();
      if (typeof toast === 'function') toast('Η πληρωμή δεν ξεκίνησε: ' + (e.message||e), 'error');
    }
  };
}
function _pluginActivatePurchase(id, mode){
  try{
    setPluginInstalled(id, true);
    // Καταγραφή τύπου χρέωσης τοπικά (για συγχρονισμό με billing αργότερα)
    try{
      var bk='zn_plugin_billing'; var map=JSON.parse(localStorage.getItem(bk)||'{}');
      var rec={ mode:mode, since:new Date().toISOString(), status:'active' };
      // Monthly subscription → set renewal date 30 days out. One-time → no expiry.
      if(mode!=='oneTime' && mode!=='once'){
        rec.expiresAt = new Date(Date.now() + 30*86400000).toISOString();
      }
      map[id]=rec;
      localStorage.setItem(bk, JSON.stringify(map));
    }catch(_){}
    var pl=(ZYRONEX_PLUGINS||[]).find(function(p){return p.id===id;});
    if(typeof toast==='function') toast('✓ Ενεργοποιήθηκε: '+(pl?pl.name:id), 'success');
    if(typeof renderPluginMarket==='function') renderPluginMarket();
    if(typeof refreshNav==='function') refreshNav();
  }catch(_){}
}
function _pluginUninstall(id){
  try {
    setPluginInstalled(id, false);
    var pl = (ZYRONEX_PLUGINS || []).find(function(p){ return p.id === id; });
    if (typeof toast === 'function') toast('Απεγκαταστάθηκε: ' + (pl ? pl.name : id), 'info');
    if (typeof renderPluginMarket === 'function') renderPluginMarket();
    if (typeof _applyPluginGates === 'function') _applyPluginGates();
  } catch(_) {}
}

// ── App-Store "Άνοιγμα": πηγαίνει στο σημείο όπου ζει το plugin ──────────────
// Κάθε plugin ανοίγει στη σελίδα/εργαλείο του. Όσα έχουν δικό τους menu entry
// (π.χ. Site Builder) πάνε κατευθείαν· τα υπόλοιπα ανοίγουν τη σελίδα-ξενιστή
// και (όπου χρειάζεται) το σωστό tab/εργαλείο.
function _pluginOpen(id){
  try {
    var routes = {
      site_builder:      function(){ showPage('sitebuilder'); },
      reorder_assistant: function(){ showPage('inventory'); setTimeout(function(){ if(typeof ZN_REORDER!=='undefined') ZN_REORDER.open(); }, 350); },
      smart_bundle:      function(){ showPage('inventory'); setTimeout(function(){ if(typeof openSmartBundle==='function') openSmartBundle(); }, 350); },
      expiry_markdown:   function(){ showPage('inventory'); setTimeout(function(){ if(typeof openExpiryMarkdown==='function') openExpiryMarkdown(); }, 350); },
      invoice_check:     function(){ showPage('inventory'); if(typeof toast==='function') toast('Σκάναρε τιμολόγιο: Αποθήκη → Smart Invoice Scanner','info'); },
      winback:           function(){ showPage('customer-intel'); setTimeout(function(){ if(typeof setCITab==='function') setCITab('winback'); }, 350); },
      basket_affinity:   function(){ showPage('customer-intel'); setTimeout(function(){ if(typeof setCITab==='function') setCITab('affinity'); }, 350); }
    };
    if (routes[id]) { routes[id](); }
    else { var pl=(ZYRONEX_PLUGINS||[]).find(function(p){return p.id===id;}); if(typeof toast==='function') toast('Άνοιξε: '+(pl?pl.location:id),'info'); }
  } catch(e) { if(typeof toast==='function') toast('Σφάλμα ανοίγματος plugin','error'); }
}

// --- theme sub-module ---
function toggleTheme(){
  const isLight = document.body.classList.toggle('light-theme');
  localStorage.setItem('katastimaTheme', isLight ? 'light' : 'dark');
  updateThemeIcon();
  toast('Θέμα: ' + (isLight ? 'Φωτεινό' : 'Σκοτεινό'), 'success');
}

function updateThemeIcon(){
  const btn = document.getElementById('themeToggle');
  if(!btn) return;
  const isLight = document.body.classList.contains('light-theme');
  btn.innerHTML = `<i data-lucide="${isLight?'sun':'moon'}" size="18"></i>`;
  lucide.createIcons();
}

function initTheme(){
  const saved = localStorage.getItem('katastimaTheme');
  if(saved === 'light'){
    document.body.classList.add('light-theme');
  }
  updateThemeIcon();
}

