/* ================================================
   === PAYMENT MODULE ===
   ================================================ */

var DEFAULT_POINT_RATES = {
  bronze:   0.010,  // 1000 pts = 10.00€
  silver:   0.012,  // 1000 pts = 12.00€
  gold:     0.015,  // 1000 pts = 15.00€
  platinum: 0.020   // 1000 pts = 20.00€
};

function getPointRates(){
  const s = typeof getSettings === 'function' ? getSettings() : {};
  return {
    bronze:   parseFloat(s.pointRateBronze   || DEFAULT_POINT_RATES.bronze),
    silver:   parseFloat(s.pointRateSilver   || DEFAULT_POINT_RATES.silver),
    gold:     parseFloat(s.pointRateGold     || DEFAULT_POINT_RATES.gold),
    platinum: parseFloat(s.pointRatePlatinum || DEFAULT_POINT_RATES.platinum),
    mode:     s.pointRateMode || 'simple'  // 'simple' | 'tiered'
  };
}

function _olEarnsPoints(){
  try{ var s=JSON.parse(localStorage.getItem('katastimaSettings')||'{}'); return s.onlineEarnsPoints!==false; }catch(e){ return true; }
}


function getPointValue(tier, rates){
  // simple mode: always bronze rate
  if(rates.mode === 'simple') return rates.bronze;
  return rates[tier||'bronze'] || rates.bronze;
}


function pointsToEur(points, tier){
  const rates = getPointRates();
  return Math.round(points * getPointValue(tier, rates) * 100) / 100;
}


function eurToPoints(amount, tier){
  const rates = getPointRates();
  const rate = getPointValue(tier, rates);
  return Math.floor(amount / rate);
}

// ── PAYMENT STATE ─────────────────────────────────────────

var SPLIT_PAYMENTS = [];  // [{method, amount, label, status, apiRef}]
var SPLIT_TOTAL    = 0;
var SPLIT_CUSTOMER = null;

function _spReset(total, customer){
  SPLIT_PAYMENTS = [];
  SPLIT_TOTAL = total;
  SPLIT_CUSTOMER = customer || null;
}


function _spRemaining(){
  const paid = SPLIT_PAYMENTS.reduce((s,p) => s + (p.amount||0), 0);
  return Math.round((SPLIT_TOTAL - paid) * 100) / 100;
}


function _spMethodLabel(method){
  const labels = {
    cash:   '💵 Μετρητά',
    card:   '💳 Κάρτα',
    iris:   '📱 IRIS',
    points: '⭐ Πόντοι',
    credit: '🏦 Store Credit',
    viva:   '🏦 Viva Wallet',
    piraeus:'🏦 Piraeus',
    stripe: '💳 Stripe',
    other:  '📋 Άλλο'
  };
  return labels[method] || method;
}

