    h += '<div style="flex:1;font-weight:700;font-size:13px">'+_spMethodLabel(p.method)+'</div>';
    h += '<div style="font-weight:900;color:#2ed573;font-size:15px">'+eur(p.amount)+'</div>';
    h += '<button type="button" onclick="_spRemovePay('+pi+')" style="background:rgba(255,71,87,0.15);border:1px solid rgba(255,71,87,0.3);border-radius:6px;color:#ff4757;padding:6px 10px;cursor:pointer;font-weight:700;font-size:12px;min-height:36px;-webkit-tap-highlight-color:transparent">✕</button>';
