    h+='<div style="font-size:11px;color:'+(TC[tier]||'#fff')+';font-weight:700">'+(TE[tier]||'')+' '+tier.toUpperCase()+'</div>';
    if(maxPointsEur>0) h+='<div style="font-size:11px;color:var(--text-3)">⭐ '+eur(maxPointsEur)+'</div>';
    if(creditBalance>0) h+='<div style="font-size:11px;color:var(--text-3)">🏦 '+eur(creditBalance)+'</div>';
