function _spApplySuggestion(idx){
  const customer = SPLIT_CUSTOMER;
  const suggestions = _spAISuggest(SPLIT_TOTAL, customer);
  const suggestion = suggestions[idx];
  if(!suggestion) return;
  SPLIT_PAYMENTS = suggestion.splits.map(s => ({
    ...s,
    note: _spBuildNote(s.method, s.amount, customer)
  }));
  _renderSplitModal(customer);
}


function _spBuildNote(method, amount, customer){
  const tier = customer?.loyaltyTier || 'bronze';
  if(method === 'points'){
    const pts = eurToPoints(amount, tier);
    return `${pts} πόντοι (${tier})`;
  }
  if(method === 'credit') return 'Υπόλοιπο πελάτη';
  return '';
}


function _spRemovePayment(idx){
  SPLIT_PAYMENTS.splice(idx, 1);
  _renderSplitModal(SPLIT_CUSTOMER);
}


function _spAddMethod(method){ _spOpenModal(method); }
function _spConfirmAddMethod(method){ _spDoNext(); }
function _spSelectMethod(method){ _spOpenModal(method); }
function _spConfirmStep(){ _spDoNext(); }

function _spConfirmStep_unused(){
  var method = window._spCurrentMethod;
  if(!method){
    if(typeof toast==='function') toast('Επίλεξε τρόπο πληρωμής','warning');
    return;
  }
  var el = document.getElementById('spInp');
  var given = parseFloat(el ? el.value : 0);
  if(!given || given <= 0){
    if(typeof toast==='function') toast('Βάλε ποσό','warning');
    return;
  }
  var remaining = _spRemaining();
  var customer  = SPLIT_CUSTOMER;
  var tier      = customer ? (customer.loyaltyTier||'bronze') : 'bronze';

  // Για cash: καταγράφουμε min(given, remaining) — τα ρέστα δεν μπαίνουν στην πώληση
  var amount = (method === 'cash') ? Math.min(given, remaining) : given;

  // Tolerance για floating point: 4.90 == 4.90
  if(method !== 'cash' && amount > remaining + 0.01){
    if(typeof toast==='function') toast('Το ποσό υπερβαίνει το υπόλοιπο ('+eur(remaining)+')','warning');
    return;
  }
  if(method === 'points'){
    var maxPts = pointsToEur(customer ? customer.loyaltyPoints||0 : 0, tier);
    if(amount > maxPts + 0.01){ if(typeof toast==='function') toast('Ανεπαρκείς πόντοι','warning'); return; }
  }
  if(method === 'credit'){
    if(amount > (customer ? customer.storeCredit||0 : 0) + 0.01){ if(typeof toast==='function') toast('Ανεπαρκές store credit','warning'); return; }
  }

  var note = _spBuildNote(method, amount, customer);
  SPLIT_PAYMENTS.push({method:method, amount:amount, note:note, status:'pending'});
  window._spCurrentMethod = null;
  _renderSplitModal(SPLIT_CUSTOMER);
}

function _spLiveChange(){
  if(window._spCurrentMethod !== 'cash') return;
  var inp       = document.getElementById('spInp');
  var changeAmt = document.getElementById('spChangeAmt');
  var changeRow = document.getElementById('spChangeRow');
  if(!inp || !changeAmt) return;
  var given     = parseFloat(inp.value) || 0;
  var remaining = _spRemaining();
  var change    = given - remaining;
  if(given > 0 && change >= -0.001){
    changeAmt.textContent = Math.max(0, change).toFixed(2) + '€';
    if(changeRow) changeRow.style.display = 'block';
  } else {
    if(changeRow) changeRow.style.display = 'none';
  }
}

window._spCurrentMethod = null;

// ── FINALIZE PAYMENT ──────────────────────────────────────

async function _spFinalize(){
  const remaining = _spRemaining();
  if(remaining > 0.005){
    if(typeof toast==='function') toast(`Υπολείπονται ${typeof eur==='function'?eur(remaining):remaining+'€'}`, 'warning');
    return;
  }

  // Κλείσε το split modal ΠΡΩΤΑ
  _spClose();
  closeModal();

  // Process each payment method
  let totalPointsUsed = 0;
  let totalCreditUsed = 0;
  const processedSplits = [];

  for(const payment of SPLIT_PAYMENTS){
    let result;
    try{
      const handler = PAYMENT_HANDLERS[payment.method];
      if(!handler){ result = {success:true, ref:'MANUAL_'+Date.now()}; }
      else { result = await handler(payment.amount, SPLIT_CUSTOMER); }
    }catch(e){
      result = {success:false, error:e.message};
    }

    if(!result.success){
      if(typeof toast==='function') toast(`❌ ${_spMethodLabel(payment.method)}: ${result.error||'Σφάλμα'}`, 'danger');
      return;
    }

    processedSplits.push({...payment, status:'completed', ref:result.ref});
    if(payment.method === 'points') totalPointsUsed += result.pointsUsed || 0;
    if(payment.method === 'credit') totalCreditUsed += payment.amount;
  }

  // Determine primary payment method label for sale record
  const primaryMethod = SPLIT_PAYMENTS.length === 1
    ? SPLIT_PAYMENTS[0].method
    : 'split';

  // Store splits for _doCheckout to use
  window._pendingSplitPayments = processedSplits;
  window._pendingPointsUsed = totalPointsUsed;
  window._pendingCreditUsed = totalCreditUsed;
  window._pendingPaymentMethod = primaryMethod;

  // Run checkout
  await _doCheckout();
}

