function _spSaveRates(){
  const mode = document.getElementById('spRateMode')?.value || 'simple';
  const s = typeof getSettings==='function' ? getSettings() : {};
  s.pointRateMode = mode;
  s.pointRateBronze = parseFloat(document.getElementById('spRateBronze')?.value)||0.010;
  s.pointRateSilver = parseFloat(document.getElementById('spRateSilver')?.value)||0.012;
  s.pointRateGold = parseFloat(document.getElementById('spRateGold')?.value)||0.015;
  s.pointRatePlatinum = parseFloat(document.getElementById('spRatePlatinum')?.value)||0.020;
  var _olChk = document.getElementById('spOnlineEarns');
  s.onlineEarnsPoints = _olChk ? _olChk.checked : true;
  localStorage.setItem('katastimaSettings', JSON.stringify(s));
  // Toggle tiered UI
  const tiered = document.getElementById('spTieredRates');
  if(tiered) tiered.style.cssText = mode==='tiered' ? '' : 'opacity:0.5;pointer-events:none';
  if(typeof toast==='function') toast('✅ Αποθηκεύτηκε', 'success');
}


// === SETTINGS MODULE ===
// --- getAppSettings ---
function getAppSettings(){
  try {
    return JSON.parse(localStorage.getItem('katastimaSettings') || '{}');
  } catch(e) {
    return {};
  }
}
window.getAppSettings = getAppSettings;

// --- saveSettings ---
function saveSettings(){
  const $val = (id, def='') => document.getElementById(id)?.value ?? def;
  const $chk = (id, def=false) => document.getElementById(id)?.checked ?? def;
  const _ex = (typeof getSettings==='function') ? getSettings() : {};
  const settings = {
    shopName: $val('s_shopName'),
    afm: $val('s_afm'),
    doy: $val('s_doy'),
    addr: $val('s_addr'),
    address: $val('s_address'),         // Αποθήκευση για το Sunmi receipt
    receiptFooter: $val('s_receiptFooter'), // Αποθήκευση για το Sunmi receipt
    city: $val('s_city'),
    phone: $val('s_phone'),
    email: $val('s_email'),
    vat: parseFloat($val('s_vat','24')) || 24,
    emailLowStock: $chk('s_emailLowStock'),
    pushNotif: $chk('s_pushNotif'),
    alertExpiry: $chk('s_alertExpiry'),
    autoReorder: $chk('s_autoReorder'),
    notifyEmail: $val('s_notifyEmail'),
    printer: $val('s_printer'),
    printMethod: $val('s_printMethod'),
    receiptFormat: $val('s_receiptFormat','80'),
    scanner: $val('s_scanner'),
    autoPrint: $chk('s_autoPrint'),
    // Daily reports
    dailyReport: $chk('s_dailyReport'),
    dailyReportTime: $val('s_dailyReportTime','10:00'),
    weeklyReport: $chk('s_weeklyReport'),
    monthlyReport: $chk('s_monthlyReport'),
    reportEmail: $val('s_reportEmail'),
    // Accountant
    // Accountant (edited in Finance → Λογιστήριο; preserve here so a general save won't blank them)
    accountantEmail: $val('s_accountantEmail', _ex.accountantEmail||''),
    accountantName: $val('s_accountantName', _ex.accountantName||''),
    accountantFromEmail: $val('s_accountantFromEmail', _ex.accountantFromEmail||''),
    accSendSales: $chk('s_accSendSales', _ex.accSendSales!==false),
    accSendShifts: $chk('s_accSendShifts', _ex.accSendShifts!==false),
    accSendCashbook: $chk('s_accSendCashbook', !!_ex.accSendCashbook),
    accSendPurchases: $chk('s_accSendPurchases', !!_ex.accSendPurchases),
    accPlatEfood: $chk('s_accPlatEfood', !!_ex.accPlatEfood),
    accPlatWolt: $chk('s_accPlatWolt', !!_ex.accPlatWolt),
    accPlatSkroutz: $chk('s_accPlatSkroutz', !!_ex.accPlatSkroutz),
    accFmtPdf: $chk('s_accFmtPdf', _ex.accFmtPdf!==false),
    accFmtCsv: $chk('s_accFmtCsv', _ex.accFmtCsv!==false),
    accAutoSend: $chk('s_accAutoSend', !!_ex.accAutoSend),
    // AADE myDATA
    aadeCompany: $val('s_aadeCompany'),
    aadeVat: $val('s_aadeVat'),
    aadeUsername: $val('s_aadeUsername'),
    aadeKey: $val('s_aadeKey'),
    aadeEnv: $val('s_aadeEnv','sandbox'),
    // Πολιτική συνδυασμού προσφορών
    promoCombination: $val('s_promoCombination', _ex.promoCombination||'best'),
  };
  localStorage.setItem('katastimaSettings', JSON.stringify(settings));
  if(typeof refreshHIDScanner === 'function') refreshHIDScanner();
  toast('Οι ρυθμίσεις αποθηκεύτηκαν','success');
}

// --- getSettings ---
function getSettings(){
  return JSON.parse(localStorage.getItem('katastimaSettings') || '{}');
}

// --- openMarginSettings ---
function openMarginSettings(){
  const current = getMarginThreshold();
  openModal(`<div class="modal-head">
    <h3 class="fw-800 text-xl">⚙️ Ρυθμίσεις Margin (Godfather)</h3>
    <button class="icon-btn" onclick="closeModal()"><i data-lucide="x" size="16"></i></button>
  </div>
  <div class="modal-body">
    <div class="ai-box mb-3" style="padding:12px">
      <div class="text-sm"><b>💡 Πώς δουλεύει:</b> Ορίζεις το ελάχιστο περιθώριο κέρδους (%). Αν κάποιο προϊόν πέσει κάτω από αυτό, θα εμφανιστεί στο Στρατηγείο ως "σε κίνδυνο" και θα απαιτείται <b>admin PIN</b> για πώληση στο ταμείο.</div>
    </div>

    <div class="form-row">
      <label class="form-label">Ελάχιστο Margin (%)</label>
      <input class="form-input" type="number" min="0" max="100" step="1" id="ms_threshold" value="${current}">
    </div>

    <div class="form-row">
      <label class="form-label">Admin PIN (για override στο POS)</label>
      <input class="form-input" type="password" id="ms_adminPin" value="${getSettings().adminPin||''}" placeholder="π.χ. 1234">
      <div class="text-xs muted mt-1">Αν κενό, το margin lock δεν θα ζητάει PIN (μόνο warning)</div>
    </div>

    <div class="flex gap-2 mt-4">
      <button class="btn btn-primary" onclick="saveMarginSettings()"><i data-lucide="save" size="16"></i> Αποθήκευση</button>
      <button class="btn btn-ghost" onclick="closeModal()">Ακύρωση</button>
    </div>
  </div>`);
  lucide.createIcons();
}

// --- saveMarginSettings ---
function saveMarginSettings(){
  const threshold = parseFloat(document.getElementById('ms_threshold').value) || 40;
  const pin = document.getElementById('ms_adminPin').value.trim();
  try{
    const settings = getSettings();
    var _oldThreshold = settings.minMarginPct || 40;
    settings.minMarginPct = threshold;
    settings.adminPin = pin || null;
    localStorage.setItem('katastimaSettings', JSON.stringify(settings));
    if(parseFloat(_oldThreshold) !== parseFloat(threshold))
      logShopChange('policy', 'The Godfather', 'Ελάχιστο περιθώριο κέρδους (%)', _oldThreshold, threshold);
    closeModal();
    toast(`✅ Threshold: ${threshold}%`,'success');
    if(window.CURRENT_PAGE_ID === 'warroom') renderWarRoom();
  }catch(e){
    toast('Σφάλμα: '+e.message,'danger');
  }
}

// --- complianceOpenSettings ---
function complianceOpenSettings(){
  var s = COMPLIANCE_CAL.getSettings();
  openModal(
    '<div class="modal-head"><h3 class="fw-800 text-xl">⚙️ Ρυθμίσεις Συμμόρφωσης</h3>'+
    '<button class="icon-btn" onclick="closeModal()"><i data-lucide="x" size="16"></i></button></div>'+
    '<div class="modal-body">'+
      '<div class="form-row"><label class="form-label">Περίοδος ΦΠΑ</label>'+
        '<select id="cc_vatPeriod" class="form-select" style="font-size:16px">'+
          '<option value="quarterly"'+(s.vatPeriod==='quarterly'?' selected':'')+'>Τριμηνιαία (απλογραφικά)</option>'+
          '<option value="monthly"'+(s.vatPeriod==='monthly'?' selected':'')+'>Μηνιαία (διπλογραφικά ή επιλογή)</option>'+
        '</select>'+
        '<div style="font-size:11.5px;color:var(--text-2);margin-top:5px">Τα περισσότερα μικρά καταστήματα: τριμηνιαία.</div></div>'+
      '<div class="form-row"><label class="form-label">Κάνεις ενδοκοινοτικές αγορές (EU);</label>'+
        '<select id="cc_intraEU" class="form-select" style="font-size:16px">'+
          '<option value="no"'+(!s.hasIntraEU?' selected':'')+'>Όχι</option>'+
          '<option value="yes"'+(s.hasIntraEU?' selected':'')+'>Ναι (εμφάνισε Φ4/Φ5)</option>'+
        '</select></div>'+
      '<div class="form-row"><label class="form-label">Προειδοποίηση πόσες μέρες πριν;</label>'+
        '<input id="cc_leadDays" type="number" min="1" max="30" class="form-input" value="'+(s.leadDays||7)+'" style="font-size:16px">'+
        '<div style="font-size:11.5px;color:var(--text-2);margin-top:5px">Οι προθεσμίες εντός αυτού του διαστήματος γίνονται 🟠 επείγουσες.</div></div>'+
    '</div>'+
    '<div class="modal-foot"><button class="btn btn-primary btn-lg" onclick="complianceSaveSettings()"><i data-lucide="save" size="16"></i> Αποθήκευση</button></div>'
  );
  if(typeof lucide !== 'undefined' && lucide.createIcons) lucide.createIcons();
}

// --- complianceSaveSettings ---
function complianceSaveSettings(){
  var s = COMPLIANCE_CAL.getSettings();
  s.vatPeriod = document.getElementById('cc_vatPeriod').value;
  s.hasIntraEU = document.getElementById('cc_intraEU').value === 'yes';
  s.leadDays = parseInt(document.getElementById('cc_leadDays').value) || 7;
  COMPLIANCE_CAL.saveSettings(s);
  closeModal();
  _renderComplianceCalendarPage();
  if(typeof complianceUpdateBadge === 'function') complianceUpdateBadge();
  toast('✅ Αποθηκεύτηκαν','success');
}

