// --- _settingsSubView ---
var _settingsSubView = false; // tracks if we're inside a settings category panel

// --- _openSettingsPanel ---
function _openSettingsPanel(catId) {
  // Mark that we're in a settings sub-view (so goBack returns to grid)
  _settingsSubView = true;
  // Render full settings inline and scroll to category anchor
  _renderSettingsInline();
  // Add a back-to-grid button at top
  setTimeout(function() {
    var c = document.getElementById('content');
    if (c && !document.getElementById('settingsBackToGrid')) {
      var backBar = document.createElement('div');
      backBar.id = 'settingsBackToGrid';
      backBar.style.cssText = 'position:sticky;top:0;z-index:50;background:var(--bg-1);padding:10px 0;margin-bottom:8px;border-bottom:1px solid var(--border)';
      backBar.innerHTML = '<button class="btn btn-ghost" style="font-size:14px" onclick="_settingsBackToGrid()">← Πίσω στις Ρυθμίσεις</button>';
      c.insertBefore(backBar, c.firstChild);
    }
    var el = document.getElementById('settings-section-' + catId);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, 80);
}

// --- _settingsBackToGrid ---
function _settingsBackToGrid() {
  _settingsSubView = false;
  renderSettings(); // re-render the grid (the override version)
  // Κράτα το tab bar συγχρονισμένο στο «Σύστημα» (οι ρυθμίσεις ανήκουν εκεί)
  try { if(typeof znSyncTabBar === 'function') znSyncTabBar('settings'); } catch(_){}
}

// --- _renderSettingsFull ---
function _renderSettingsFull(container) {
  const s = JSON.parse(localStorage.getItem('katastimaSettings') || '{}');
  // We need the old renderSettings HTML — call it temporarily
  const origContent = document.getElementById('content');
  const tempHolder = document.createElement('div');
  tempHolder.id = '_settingsTemp';
  tempHolder.style.display = 'none';
  document.body.appendChild(tempHolder);

  // Swap content div, render, capture, restore
  tempHolder.innerHTML = '';
  const oldId = origContent.id;
  origContent.id = '_settingsReal';
  tempHolder.id = 'content';
  _renderSettingsOld();
  container.innerHTML = tempHolder.innerHTML;
  tempHolder.id = '_settingsTemp';
  origContent.id = oldId;
  document.body.removeChild(tempHolder);
}

// --- _kioskRenderSettings ---
function _kioskRenderSettings(){
  const isAdmin=CURRENT_USER&&(CURRENT_USER.perms||[]).includes('*');
  if(!isAdmin){toast('Μόνο για Admin','warn');return;}
  // Reset preview flag κάθε φορά που ανοίγει φρέσκια η σελίδα ρυθμίσεων
  window._kioskPreviewShown = false;
  const cfg=_kioskGetConfig();
  const timeout=cfg.idleTimeout||180;
  const disabled=cfg.idleDisabled||false;
  const el=document.getElementById('content');
  if(!el)return;
  el.innerHTML=`
  <div class="page-head">
    <div><div class="page-title">🖥️ Kiosk & Idle Screen</div>
    <div class="page-sub">Ρυθμίσεις οθόνης αναμονής και πελατών</div></div>
  </div>
  <div style="max-width:660px;display:flex;flex-direction:column;gap:16px">
    <div class="card" style="padding:20px">
      <div style="font-size:13px;font-weight:700;color:var(--text-0);margin-bottom:14px">Προεπισκόπηση</div>
      <div style="display:flex;gap:12px;flex-wrap:wrap">
        <button class="btn btn-primary" onclick="renderKiosk('kiosk')">🛍️ Kiosk Mode (Πελάτης)</button>
        <button class="btn btn-ghost" onclick="renderKiosk('idle')">🖥️ Idle Screen (Αναμονή)</button>
      </div>
    </div>
    <div class="card" style="padding:20px">
      <div style="font-size:13px;font-weight:700;color:var(--text-0);margin-bottom:16px">⚙️ Ρυθμίσεις Idle Screen</div>
      <div style="display:flex;align-items:center;justify-content:space-between;padding:14px;background:var(--bg-2);border-radius:12px;margin-bottom:12px">
        <div>
          <div style="font-size:13px;font-weight:600">Idle Screen</div>
          <div style="font-size:11px;color:var(--text-2);margin-top:2px">Ενεργοποίηση οθόνης αναμονής</div>
        </div>
        <label style="position:relative;display:inline-block;width:46px;height:26px;cursor:pointer;flex-shrink:0">
          <input type="checkbox" id="kioskIdleEnabled" ${disabled?'':'checked'} onchange="_kioskToggleIdleEnabled(this.checked)" style="opacity:0;width:0;height:0;position:absolute">
          <span style="position:absolute;inset:0;border-radius:13px;background:${disabled?'var(--border)':'var(--accent)'};transition:.3s" id="kioskToggleTrack"></span>
          <span style="position:absolute;top:3px;left:${disabled?'3':'23'}px;width:20px;height:20px;border-radius:50%;background:#fff;transition:.3s;box-shadow:0 1px 4px rgba(0,0,0,.3)" id="kioskToggleThumb"></span>
        </label>
      </div>
      <div id="kioskTimeoutRow" style="padding:14px;background:var(--bg-2);border-radius:12px;${disabled?'opacity:.4;pointer-events:none':''}">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
          <div><div style="font-size:13px;font-weight:600">Χρόνος Αδράνειας</div>
          <div style="font-size:11px;color:var(--text-2);margin-top:2px">Χρόνος πριν μπει σε αναμονή</div></div>
          <div id="kioskTimeoutVal" style="font-size:20px;font-weight:800;color:var(--accent)">${(function(){const m={60:'1 λεπτό',120:'2 λεπτά',180:'3 λεπτά',240:'4 λεπτά',300:'5 λεπτά',600:'10 λεπτά',900:'15 λεπτά',1800:'30 λεπτά',3600:'60 λεπτά'};return m[timeout]||'3 λεπτά';})()}</div>
        </div>
        <!-- Slider με διακριτές τιμές (index 0-8) -->
        <div style="position:relative">
          <input type="range" min="0" max="8" step="1"
            value="${[60,120,180,240,300,600,900,1800,3600].indexOf(timeout)<0?2:[60,120,180,240,300,600,900,1800,3600].indexOf(timeout)}"
            oninput="_kioskSliderChange(this.value)"
            style="width:100%;accent-color:var(--accent)">
          <div id="kioskSliderTicks" style="display:flex;justify-content:space-between;margin-top:8px"></div>
        </div>
      </div>
    </div>
    <div class="card" style="padding:20px">
      <div style="font-size:13px;font-weight:700;color:var(--text-0);margin-bottom:14px">🔗 Google Review Link</div>
      <div style="font-size:12px;color:var(--text-2);margin-bottom:10px">URL αξιολόγησης Google για το κουμπί "Αξιολόγηση" στο Kiosk</div>
      <input type="url" id="kioskGoogleReviewUrl"
        value="${(typeof getAppSettings==='function'?getAppSettings().googleReviewUrl:'')||''}"
        placeholder="https://g.page/r/..."
        style="width:100%;padding:10px 12px;border-radius:10px;border:1px solid var(--border);background:var(--bg-2);color:var(--text-0);font-size:13px;font-family:inherit;-webkit-appearance:none"
        oninput="_kioskSaveGoogleReview(this.value)">
    </div>
    <div class="card" style="padding:14px;background:rgba(251,191,36,.06);border:1px solid rgba(251,191,36,.25);margin-bottom:0">
      <div style="font-size:12px;color:var(--text-1);line-height:1.6">
        <b style="color:#fbbf24">ℹ️ Σημείωση:</b> Ο χρόνος αδράνειας αφορά <b>ΜΟΝΟ το τερματικό του ταμείου</b>. Όταν περάσει ο χρόνος χωρίς δραστηριότητα, ανοίγει αυτόματα η οθόνη πελάτη (Kiosk). Οι συσκευές που είναι ήδη εγγεγραμμένες ως Kiosk ξεκινούν κατευθείαν σε kiosk mode και δεν επηρεάζονται.
      </div>
    </div>

    <div class="card" style="padding:16px;background:rgba(0,212,168,.05);border:1px solid rgba(0,212,168,.2)">
      <div style="font-size:12px;color:var(--text-2);line-height:1.6">
        <b style="color:var(--accent)">🖥️ Idle Screen</b> — Σκούρο θέμα για τον υπάλληλο.<br>
        <b style="color:#f472b6">🛍️ Kiosk Mode</b> — Gradient οθόνη για τον πελάτη.<br>
        <b style="color:#d97706">🔐 Έξοδος από Kiosk</b> — Τριπλό tap στην ώρα → PIN.
      </div>
    </div>

    <!-- Device Registration -->
    <div class="card" style="padding:20px" id="deviceRegCard">
      <div style="font-size:13px;font-weight:700;color:var(--text-0);margin-bottom:6px">📱 Εγγραφή Συσκευής</div>
      <div style="font-size:12px;color:var(--text-2);margin-bottom:14px;line-height:1.5">
        Εγγραφή αυτής της συσκευής ως <b>Kiosk tablet</b>. Μόλις εγγραφεί, κάθε φορά που ανοίγει η εφαρμογή ξεκινά αυτόματα σε kiosk mode.
      </div>
      <div id="deviceRegStatus" style="margin-bottom:12px;font-size:12px"></div>
      <div style="display:flex;gap:10px;flex-wrap:wrap">
        <button class="btn btn-primary" onclick="_registerAsKiosk()" style="font-size:13px">
          📺 Εγγραφή ως Kiosk Device
        </button>
        <button class="btn btn-ghost" onclick="_unregisterDevice()" style="font-size:13px">
          🗑️ Κατάργηση Εγγραφής
        </button>
      </div>
      <div style="font-size:10px;color:var(--text-2);margin-top:10px;font-family:monospace" id="deviceUuidDisplay"></div>
    </div>
  </div>`;
}



