function handleReactivation(previousExpiry) {
  localStorage.setItem('vs_data_gap',JSON.stringify({
    suspendedAt:previousExpiry,
    reactivatedAt:new Date().toISOString(),
    acknowledged:false
  }));
  const sc=document.getElementById('suspendedScreen');if(sc)sc.className='';
  window._scheduledReportsBlocked=false;
  window._shiftRemindersBlocked=false;
  window._bankingSyncBlocked=false;
  loadSubscription().then(()=>{
    renderSubBanner();
    checkAndShowDataGapBanner();
    if(typeof toast==='function')toast('✅ Συνδρομή ενεργοποιήθηκε! Καλώς ήρθατε ξανά.','success');
  });
}

// ── MAIN INIT ────────────────────────────────────────────────────────────────

// === ROUTER HELPERS (back-btn, sidebar-perms, goBack) ===

function _updateBackBtn() {
  var btn  = document.getElementById('tabBarBackBtn');
  var fBtn = document.getElementById('floatingBackBtn');
  var logo = document.getElementById('topbarLogo');
  var search = document.getElementById('topbarSearch');

  var hist = window._pageHistory || [];
  var currentPage = hist[hist.length - 1] || 'dashboard';
  var onDashboard = (currentPage === 'dashboard');

  // Determine whether there is anywhere to go back to
  var canGoBack = false;
  if (!onDashboard) {
    var inKB = (currentPage === 'help');
    var hasKBHistory = inKB && window._helpDocHistory && window._helpDocHistory.length >= 1;
    canGoBack = hasKBHistory
      || (typeof _settingsSubView !== 'undefined' && _settingsSubView)
      || hist.length >= 2;
  }

  // Tab bar back button (mobile — inside #znTabBar)
  if (btn) btn.style.display = canGoBack ? 'flex' : 'none';

  // Floating back button (desktop — fixed position, CSS controls desktop-only visibility)
  if (fBtn) fBtn.style.display = canGoBack ? 'flex' : 'none';

  // Logo: always visible
  if (logo) {
    logo.style.display = 'flex';
    var logoUrl = (typeof getCustomLogo === 'function') ? getCustomLogo() : null;
    var settings = {};
    try { settings = typeof getAppSettings === 'function' ? getAppSettings() : {}; } catch(e){}
    var logoImg  = document.getElementById('topbarLogoImg');
    var logoName = document.getElementById('topbarLogoName');
    if (logoUrl && logoImg) {
      logoImg.src = logoUrl;
      logoImg.style.display = 'block';
      if (logoName) logoName.style.display = 'none';
    } else {
      if (logoImg) logoImg.style.display = 'none';
      if (logoName) {
        logoName.textContent = settings.shopName || 'ZyroNex';
        logoName.style.display = 'block';
      }
    }
  }
  // Search: only on desktop (CSS hides on mobile via display:none)
  if (search) {
    search.style.display = (window.innerWidth >= 768 ? 'flex' : 'none');
  }
}

function goBack() {
  // PRIORITY -1: ZNNav overlay stack (kiosk, sub-panels, custom screens) — HIGHEST priority
  if (window.ZNNav && window.ZNNav.hasOverlay()) {
    window.ZNNav.closeTop();
    return;
  }
  // PRIORITY -0.5: Αν είμαστε στη σελίδα ρυθμίσεων Kiosk, το πρώτο swipe/back
  // ανοίγει το Kiosk overlay (προεπισκόπηση). Το επόμενο swipe (αφού κλείσει
  // το preview) πάει κανονικά πίσω — αποφυγή ατέρμονου βρόχου.
  var _curPg = window._pageHistory && window._pageHistory[window._pageHistory.length - 1];
  if (_curPg === 'kiosk' && typeof renderKiosk === 'function' && !window._kioskPreviewShown) {
    window._kioskPreviewShown = true;
    renderKiosk('kiosk');
    return;
  }
  // Reset το flag όταν φεύγουμε από τη σελίδα kiosk
  if (_curPg !== 'kiosk') window._kioskPreviewShown = false;
  // PRIORITY -0.4: Site Builder — back βγαίνει στο dashboard (ΟΧΙ στο Plugin Market
  // απ' όπου ήρθες). Τα εσωτερικά overlays του editor τα έχει ήδη πιάσει το ZNNav.
  if (_curPg === 'sitebuilder' && typeof window.ZBUI !== 'undefined' && window.ZBUI && typeof window.ZBUI.exit === 'function') {
    window.ZBUI.exit();
    return;
  }
  // PRIORITY 0: If we're inside a settings category panel, return to settings grid
  if (typeof _settingsSubView !== 'undefined' && _settingsSubView) {
    _settingsBackToGrid();
    return;
  }
  // PRIORITY 1: If we're inside a KB article, go back through KB history first
  var currentPage = window._pageHistory[window._pageHistory.length - 1];
  if (currentPage === 'help' && window._helpDocHistory && window._helpDocHistory.length > 1) {
    // Go back through KB articles
    window._helpDocHistory.pop(); // remove current article
    var prevDoc = window._helpDocHistory[window._helpDocHistory.length - 1];
    if (prevDoc && typeof helpOpenDoc === 'function') {
      window._helpDocHistory.pop(); // helpOpenDoc will re-push
      helpOpenDoc(prevDoc);
      return;
    }
  }
  // PRIORITY 2: Inside a single KB article → back to KB home (welcome grid)
  if (currentPage === 'help' && window._helpDocHistory && window._helpDocHistory.length === 1) {
    window._helpDocHistory = [];
    if (typeof helpRenderWelcomeInArea === 'function') {
      helpRenderWelcomeInArea();
      return;
    }
  }
  // PRIORITY 2.7: Inside ZyroNex Vault folder → go up one folder, not out of the page
  if (currentPage === 'vault' && typeof VAULT_STATE !== 'undefined' && VAULT_STATE.path && VAULT_STATE.path.length > 0) {
    VAULT_STATE.path.pop();
    try { localStorage.setItem('vault_path', JSON.stringify(VAULT_STATE.path)); } catch(e) {}
    if (typeof renderVault === 'function') renderVault();
    return;
  }
  // PRIORITY 3: Pop the actual previous page from the history stack.
  var h = window._pageHistory || [];
  if (h.length < 2) return;       // at root — nothing to go back to
  h.pop();                        // remove current page from stack
  var prev = h[h.length - 1];
  if (!prev) return;
  window._navByBack = true;
  showPage(prev);
}

function applyPermissionsToSidebar(){
  if(!CURRENT_USER) return;
  const isDev = (typeof isDeveloperOwner === 'function' && isDeveloperOwner());
  const isAdmin = isDev || CURRENT_USER.perms?.includes('*');
  // Show/hide individual items
  document.querySelectorAll('.nav-item[data-page]').forEach(el=>{
    const page = el.dataset.page;
    const need = PAGE_PERMS[page];
    if(page === 'dashboard'){ el.style.display=''; return; }
    // Developer-only pages — μόνο για IS_DEVELOPER_OWNER shops
    if(page === 'inspector-competitors'){
      el.style.display = isDev ? '' : 'none';
      return;
    }
    // Super-admin-only: AI Cost dashboard — locked to the ZyroNex operator, no tenant admin sees it
    if(page === 'aicost'){
      el.style.display = (typeof _isSuperAdmin === 'function' && _isSuperAdmin()) ? '' : 'none';
      return;
    }
    el.style.display = (isAdmin || !need || can(need)) ? '' : 'none';
  });
  // Show/hide section headers based on whether group has visible items
  // Never touch nav-group display — only the header
  document.querySelectorAll('.sidebar .nav-section[data-section]').forEach(sec=>{
    const group = document.getElementById('nav-' + sec.dataset.section);
    if(!group){ sec.style.display=''; return; }
    const anyVisible = Array.from(group.querySelectorAll('.nav-item[data-page]'))
      .some(item => item.style.display !== 'none');
    sec.style.display = anyVisible ? '' : 'none';
    // Never hide the group itself — that's for collapse toggle only
  });
}


// ── AI COST DASHBOARD (super-admin ONLY — locked to ZyroNex operator) ──────────
async function renderAICost(){
  var c = document.getElementById('content');
  if(!c) return;
  if(!(typeof _isSuperAdmin==='function' && _isSuperAdmin())){
    c.innerHTML = '<div class="card" style="padding:48px;text-align:center"><div style="font-size:44px">🔒</div><h2 style="margin:12px 0 6px">Μη διαθέσιμο</h2><p style="color:var(--text-2)">Διαθέσιμο μόνο στον διαχειριστή του ZyroNex.</p></div>';
    return;
  }
  c.innerHTML = '<div class="card" style="padding:48px;text-align:center"><div style="font-size:32px">💰</div><h2 style="margin:10px 0">AI Κόστος</h2><p style="color:var(--text-2)">Φόρτωση χρήσης…</p></div>';
  try{
    var SB = 'https://wopyucsdaeamywscxfzs.supabase.co';
    var sid = (typeof SHOP_ID!=='undefined')?SHOP_ID:'';
    var key = (typeof SUPABASE_KEY!=='undefined'?SUPABASE_KEY:(window.SUPABASE_KEY||''));
    var resp = await fetch(SB+'/functions/v1/admin-usage', {
      method:'POST',
      headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},
      body: JSON.stringify({ shop_id: sid, days: 30 })
    });
    if(!resp.ok){ var et=await resp.text(); throw new Error('HTTP '+resp.status+' '+et.slice(0,120)); }
    var d = await resp.json();
    if(d && d.error) throw new Error(d.error);
    var usd = function(n){ return '$'+(Number(n)||0).toFixed(2); };
    var num = function(n){ return (Number(n)||0).toLocaleString('el-GR'); };
    var t = d.totals||{};
    var rows = function(arr, cols){
      return (arr||[]).map(function(r){
        return '<tr>'+cols.map(function(col){
          var v = r[col.k];
          return '<td style="padding:8px 10px;border-bottom:1px solid var(--border);'+(col.r?'text-align:right;font-variant-numeric:tabular-nums':'')+'">'+(col.f?col.f(v):(v==null?'—':v))+'</td>';
        }).join('')+'</tr>';
      }).join('');
    };
    var card = function(label,val,sub){
      return '<div class="card" style="padding:16px;flex:1;min-width:150px"><div style="font-size:12px;color:var(--text-2);text-transform:uppercase;letter-spacing:.5px">'+label+'</div><div style="font-size:26px;font-weight:800;margin-top:4px">'+val+'</div>'+(sub?'<div style="font-size:12px;color:var(--text-2);margin-top:2px">'+sub+'</div>':'')+'</div>';
    };
    c.innerHTML =
      '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:14px">'+
        '<h2 style="margin:0">💰 AI Κόστος <span style="font-size:13px;color:var(--text-2);font-weight:500">(τελευταίες '+(d.days||30)+' μέρες)</span></h2>'+
        '<button class="btn btn-ghost" onclick="renderAICost()"><i data-lucide="refresh-cw" size="15"></i> Ανανέωση</button>'+
      '</div>'+
      '<div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:16px">'+
        card('Συνολικό κόστος', usd(t.cost), num(t.calls)+' κλήσεις')+
        card('Cache hit', (Number(d.cache_hit_pct)||0).toFixed(1)+'%', 'στα input tokens')+
        card('Εξοικονόμηση', usd(d.saved), 'από caching')+
        card('Tokens (in/out)', num(t.input)+' / '+num(t.output), num(t.cache_read)+' cached')+
      '</div>'+
      '<div class="card" style="padding:0;overflow:hidden;margin-bottom:14px"><div style="padding:12px 14px;font-weight:800;border-bottom:1px solid var(--border)">Ανά μοντέλο</div>'+
        '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="color:var(--text-2);text-align:left">'+
          '<th style="padding:8px 10px">Μοντέλο</th><th style="padding:8px 10px;text-align:right">Κλήσεις</th><th style="padding:8px 10px;text-align:right">Input</th><th style="padding:8px 10px;text-align:right">Output</th><th style="padding:8px 10px;text-align:right">Cache read</th><th style="padding:8px 10px;text-align:right">Κόστος</th>'+
        '</tr></thead><tbody>'+rows(d.by_model,[{k:'model'},{k:'calls',r:1,f:num},{k:'input',r:1,f:num},{k:'output',r:1,f:num},{k:'cache_read',r:1,f:num},{k:'cost',r:1,f:usd}])+'</tbody></table></div></div>'+
      '<div style="display:flex;gap:14px;flex-wrap:wrap">'+
        '<div class="card" style="padding:0;overflow:hidden;flex:1;min-width:280px"><div style="padding:12px 14px;font-weight:800;border-bottom:1px solid var(--border)">Ανά feature (tier)</div>'+
          '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="color:var(--text-2);text-align:left"><th style="padding:8px 10px">Tier</th><th style="padding:8px 10px;text-align:right">Κλήσεις</th><th style="padding:8px 10px;text-align:right">Κόστος</th></tr></thead><tbody>'+rows(d.by_feature,[{k:'tier'},{k:'calls',r:1,f:num},{k:'cost',r:1,f:usd}])+'</tbody></table></div></div>'+
        '<div class="card" style="padding:0;overflow:hidden;flex:1;min-width:280px"><div style="padding:12px 14px;font-weight:800;border-bottom:1px solid var(--border)">Ανά κατάστημα</div>'+
          '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="color:var(--text-2);text-align:left"><th style="padding:8px 10px">Shop</th><th style="padding:8px 10px;text-align:right">Κλήσεις</th><th style="padding:8px 10px;text-align:right">Κόστος</th></tr></thead><tbody>'+rows(d.by_shop,[{k:'shop_id',f:function(v){return v?String(v).slice(0,8):'—';}},{k:'calls',r:1,f:num},{k:'cost',r:1,f:usd}])+'</tbody></table></div></div>'+
      '</div>';
    if(typeof lucide!=='undefined'&&lucide.createIcons) lucide.createIcons();
  }catch(e){
    c.innerHTML = '<div class="card" style="padding:30px"><h2>💰 AI Κόστος</h2><p style="color:var(--danger)">Σφάλμα: '+((e&&e.message)||e)+'</p><p style="color:var(--text-2);font-size:13px">Αν το edge function <b>admin-usage</b> δεν έχει γίνει deploy ακόμα, αυτό είναι αναμενόμενο μέχρι το deploy.</p></div>';
  }
}
window.renderAICost = renderAICost;
